// Explanations are deliberately attached to the exact IDs of the curated atlas.
// Java snippets use JDK 21 syntax. Framework snippets are focused excerpts,
// requiring the corresponding dependency, imports, configuration and schema.
export const conceptDetails = {};
function put(id, definition, mechanism, exampleCode, language, decision, boundaries, verify, source) {
  conceptDetails[id] = {definition, mechanism: mechanism.split('¦'), exampleCode, language, decision, boundaries, verify, ...(source ? {source} : {})};
}
const JLS = 'https://docs.oracle.com/javase/specs/jls/se21/html/index.html';
const JAVA = 'https://docs.oracle.com/en/java/javase/21/docs/api/index.html';
const MYSQL = 'https://dev.mysql.com/doc/refman/8.4/en/';
const MVC = 'https://docs.spring.io/spring-framework/reference/web/webmvc.html';
const TX = 'https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/annotations.html';
const MYBATIS = 'https://mybatis.org/mybatis-3/sqlmap-xml.html';

put('foundation-1', '计算机是执行指令并保存、传送数据的系统。CPU负责运算，RAM保存活跃数据，磁盘负责持久存储，网卡负责通信；它们的速度、容量与故障形式不同。', '启动Java进程时，操作系统分配地址空间并加载程序文件。¦收到请求后，网络数据进入缓冲区；CPU执行解析、校验和业务指令。¦Employee对象占内存，数据库写入还涉及数据库进程与存储设备。¦响应离开网卡时，数据库提交与客户端接收是两个独立确认点。', '# Linux只读观察示例\nlscpu        # CPU信息\nfree -h      # 系统内存，不等于JVM堆上限\ndf -h        # 文件系统剩余容量\nss -lnt      # 监听端口', 'plaintext', '排查资源瓶颈时，先区分CPU忙、内存紧张、磁盘等待还是网络等待，再选择工具；简单业务不需要先改硬件。', '磁盘有空间不意味着堆有空间。虚拟机、容器限额与物理机器总量也不同；硬件资源正常仍可能有锁或业务问题。', '在同一负载下对齐CPU、内存、磁盘延迟与请求时间；若SQL等待变长而CPU低，应继续查看数据库与连接等待。');
put('foundation-2', '链表是一种节点通过引用相连的存储结构；栈和队列是访问顺序的抽象。栈后进先出，队列先进先出，二者可用不同底层结构实现。', '栈push压入，pop移除最后加入的元素，适合回退与深度优先遍历。¦队列offer入队，poll取最早元素，适合按到达顺序分配任务。¦链表沿next访问节点；给定节点可局部插入，但按索引查找要遍历。', 'Deque<String> stack = new ArrayDeque<>();\nstack.push("A"); stack.push("B");\nSystem.out.println(stack.pop()); // B\nQueue<String> queue = new ArrayDeque<>();\nqueue.offer("A"); queue.offer("B");\nSystem.out.println(queue.poll()); // A', 'java', '按需要的操作语义选结构：回退用栈，待处理任务用队列；只是按索引读列表时通常先考虑数组型列表。', 'ArrayDeque不是线程安全容器；排队结构不会自己限制容量。链表插入快的前提是已经定位到节点。', '用A、B、C验证取出顺序；改变n测按索引遍历链表的耗时；并发任务应另验证容器与容量策略。', JAVA);
put('foundation-3', '树是无环且有层级的连接结构；图由顶点与边描述一般关系，可有环。业务部门树、数据库B+树和服务依赖图虽然都用节点，但目标不同。', '部门树从根向子部门展开，每个非根节点通常有一个父部门。¦搜索可用DFS或BFS；一般图必须记录已访问节点以避免循环。¦数据库索引树组织有序键与访问路径，不是业务组织层级。', 'Map<String,List<String>> graph = Map.of(\n  "web", List.of("employee"),\n  "employee", List.of("db", "notify"));\nSet<String> seen = new HashSet<>();\nQueue<String> todo = new ArrayDeque<>();\ntodo.add("web");\nwhile (!todo.isEmpty()) {\n  String node = todo.poll();\n  if (!seen.add(node)) continue;\n  todo.addAll(graph.getOrDefault(node, List.of()));\n}', 'java', '层级展示用树，任意调用与依赖用图；选择遍历方式由路径、层次或环检测目标决定。', '图上有连接不代表调用一定发生；依赖图也不能直接给出某次请求的执行时序。', '加入employee→web的环，验证遍历会结束；部门新增时检查父节点存在和不得形成环。');
put('foundation-4', '复杂度描述输入规模增长对工作量的影响。排序重排元素，查找定位元素；比较渐近阶之外还要考虑数据分布、内存与实际IO。', '线性查找最坏检查n个元素；对已排序随机访问数组，二分每次把候选区间缩小约一半。¦排序通常先付出工作量，后续查询次数足够多时才可能摊薄成本。¦数据库查询还受索引、回表与网络影响，不能把内存算法结论机械搬过去。', 'int[] ids = {2, 4, 7, 11, 19};\nint index = Arrays.binarySearch(ids, 11);\nSystem.out.println(index); // 3\n// 前提：按相同顺序已排序；返回值不是id本身', 'java', '大量查询且数据可排序时考虑二分或索引；一次性小集合扫描可能更简单。', 'O(log n)不保证比O(n)在每个小输入上快；最坏、平均和摊还复杂度要分别说明。', '用有序与乱序数据对比结果；以1千、1万、10万输入观察增长趋势，而不只测一次纳秒值。', JAVA);
put('foundation-5', 'OSI七层是解释网络职责的模型；TCP/IP模型更贴近互联网协议组合。HTTP负责应用语义，TCP负责可靠字节流，IP负责寻址与路由，链路层负责一跳传送。', '应用把请求编码成字节，TLS可在HTTP与传输之间加密。¦TCP把字节组织为传输段；IP把它们送到目标地址，可经过多跳路由。¦每一跳使用对应链路帧；服务端逐层接收后由HTTP解析器还原请求。', '应用语义：POST /admin/employee + JSON\n传输语义：TCP有序字节流\n网络语义：源IP → 目标IP\n链路语义：本跳接口 → 下一跳接口', 'plaintext', '用分层判断失败范围：HTTP403不同于TCP连接拒绝；解释链路时比背七层编号更有用。', '现代HTTPS也可能使用HTTP/3 over QUIC/UDP，本教学TCP链不是所有HTTP的唯一实现。网路分层不等于每层一个独立进程。', '浏览器Network查看状态与协议，抓包查看传输层；TLS加密时抓包通常不能直接看到正文。');
put('foundation-6', 'DNS把名称解析成地址等记录；TCP交付有序可靠字节流；UDP提供独立数据报；Socket是操作系统给程序的网络接口。它们不是四个必经业务层。', '程序根据域名查询地址，缓存可能直接给出结果。¦TCP客户端建立连接后读写流；UDP客户端可发数据报而无需TCP式连接。¦服务端按应用协议处理读取的字节：一次read可能只得到部分消息或多条消息。', 'try (Socket socket = new Socket("example.com", 80)) {\n  socket.getOutputStream().write(\n    "GET / HTTP/1.1\\r\\nHost: example.com\\r\\nConnection: close\\r\\n\\r\\n"\n      .getBytes(StandardCharsets.US_ASCII));\n  System.out.println(socket.getInputStream().read());\n}', 'java', '日常HTTP优先用成熟客户端库；理解Socket有助于解释超时、连接和消息边界，不必业务层手写协议。', '示例只读一个字节，不是完整HTTP客户端。UDP不保证交付或顺序；TCP可靠也不保证业务操作恰好一次。', '让服务器分两次写一条消息，观察客户端必须继续读取；分别模拟DNS失败、端口拒绝和读取超时。', JAVA);
put('foundation-7', '进程是资源与隔离边界，线程是进程中的执行路径。多个线程共享进程内存；操作系统调度让就绪线程获得CPU，阻塞等待的线程并非一直运算。', 'Tomcat为请求安排执行资源，业务代码在工作线程上运行。¦线程等待JDBC时可能阻塞，CPU可调度别的线程。¦更多线程提高某些等待场景的并发，也增加栈、调度和竞争成本。', 'Thread worker = Thread.ofPlatform().start(() -> {\n  System.out.println(Thread.currentThread().getName());\n});\nworker.join(); // 主线程等待worker结束', 'java', '区分CPU计算与IO等待再评估线程数；Java21虚拟线程是另一执行策略，但不能扩大数据库实际容量。', '调用run只是当前线程执行普通方法；start才启动线程。线程安全问题来自共享可变状态，不仅来自线程数量。', '线程转储观察RUNNABLE、WAITING与BLOCKED及栈位置，再与CPU时间对照；不要凭状态名称独立判定根因。', JAVA);
put('foundation-8', '虚拟内存给进程地址空间，文件系统管理命名与持久文件，锁限制并发访问。内存中的对象、磁盘文件与共享资源的互斥是三个不同问题。', '程序分配对象后，通过引用访问内存状态。¦持久化经文件或数据库写入，再按具体刷新规则进入持久存储。¦两个执行者更新同一状态时，必须采用同一保护边界或原子写约束。', 'Object guard = new Object();\nint[] value = {0};\nsynchronized (guard) { value[0]++; }\nFiles.writeString(Path.of("note.txt"), "saved");\n// 写文件成功与数据库事务提交不是同一件事', 'java', '单进程状态可用Java锁，跨实例数据库规则应交给数据库约束或正确的分布式协调。', '文件写入返回不必然代表所有硬件故障下已耐久；对不同guard加锁不能互斥。', '让两个线程分别使用同一锁与不同锁更新，比较结果；跨实例实验验证本地锁无法协调另一进程。', JAVA);
put('foundation-9', '关系模型用表、键和关系组织数据；范式减少重复造成的异常；事务组合操作；索引提供访问路径。它们分别处理建模、正确性、执行边界和查询成本。', '部门和员工拆为两表，以department_id关联。¦唯一约束表达username不可重复，外键是否采用要结合设计。¦事务控制一组写入的提交回滚；索引帮助快速找到目标行。', 'CREATE TABLE department(id BIGINT PRIMARY KEY, name VARCHAR(50));\nCREATE TABLE employee(\n  id BIGINT PRIMARY KEY,\n  username VARCHAR(50) NOT NULL UNIQUE,\n  department_id BIGINT\n);\nSELECT e.username, d.name\nFROM employee e LEFT JOIN department d ON d.id=e.department_id;', 'sql', '先写业务不变量与查询模式，再决定表、约束与索引；不要先画几十张表再猜业务。', '索引不替代事务，事务不自动验证所有业务规则，范式也不保证每个查询最快。', '并发插入同名员工验证约束；执行EXPLAIN验证连接键访问路径；回滚验证多写操作边界。', MYSQL);
put('foundation-10', 'Linux命令用来观察和控制文件、进程、权限与网络。权限分属主、组和其他用户；能读文件、能执行程序和能访问目录是不同许可。', '确认服务运行的用户、PID与监听地址。¦读取日志定位启动或请求错误，再检查文件与目录权限。¦只修改确有需要的权限，并验证服务账户仍能运行。', 'id\nps -ef\nss -lntp\nls -l /opt/app\njournalctl -u employee-app --since "10 minutes ago"\n# 每条命令的路径和服务名应按实际环境替换', 'plaintext', '部署和排错需要理解这些证据；普通功能开发可先使用本地环境，不必先搭复杂主机管理。', 'chmod 777不是通用修复。Windows与Linux命令不同；系统防火墙、容器端口映射也会影响连通性。', '用实际服务账户读取配置、写日志并访问端口；确认监听127.0.0.1与0.0.0.0的可达范围差异。');
put('foundation-11', 'Git保存版本快照与提交关系，GitHub提供托管评审和自动化。提交、推送、合并、构建和部署是不同节点，不能混为“上线”。', '工作区编辑后形成diff，暂存选择本次改动。¦提交产生可引用版本，推送让协作者取得它。¦Pull Request评审与CI检查后合并；部署再把特定制品运行起来。', 'git status\ngit diff\ngit add src/EmployeeService.java\ngit commit -m "Validate employee creation"\n# 提交仅改变本地版本历史；发布由独立流程完成', 'plaintext', '使用小而完整的提交保留可审查行为；多人协作或长期项目需要版本管理，不必为了简单笔记引入复杂分支流程。', 'Git不会自动删除已泄露秘密；删除当前文件也不等于历史中已消失。合并通过不等于线上行为正确。', '确认提交SHA、CI结果与运行版本一致；用新环境从仓库构建，排除只在本机存在的配置。');
put('foundation-12', '面向对象把职责、状态与行为放进协作对象；模式描述特定问题的常见解法。封装与可替换接口是基础，模式是按需求选择的结构。', '先定位变化点，如短信供应商可能替换。¦用接口固定业务所需能力，实现适配供应商细节。¦Service调用接口而不依赖供应商请求格式，测试也可提供替身。', 'interface Notifier { void send(String recipient); }\nclass EmployeeService {\n  private final Notifier notifier;\n  EmployeeService(Notifier n) { this.notifier = n; }\n  void invite(String phone) { notifier.send(phone); }\n}', 'java', '真正存在替换、复杂协作或测试隔离需求时引入接口；稳定而简单的内部逻辑不必为每个类建空接口。', '继承不是唯一复用手段；“用了策略模式”只有在明确策略变化和调用边界后才有意义。', '替换Notifier实现而不改Service，验证契约仍成立；观察模式是否减少了实际改动范围。');

put('javase-1', 'Java语言定义源码语义，JVM执行class字节码，JDK提供编译与诊断等开发工具。JRE是运行环境的概念，现代发行版的提供形式不能按旧安装教程一概而论。', 'javac读取源码并按语言版本编译为class文件。¦java启动JVM，加载主类及其依赖并执行main。¦运行过程中JVM解释或编译字节码，标准库提供集合、IO等能力。', '// Hello.java，JDK21\npublic class Hello {\n  public static void main(String[] args) {\n    System.out.println("Java request chain");\n  }\n}\n// 终端：javac Hello.java；java Hello', 'java', '先确认构建与运行的JDK版本，解决class版本不兼容；不必把JVM具体优化实现当语言语法来记。', 'JDK21不是本网站认定的唯一生产版本。框架支持版本、发行版支持周期与语言版本需分别核对。', 'java -version与javac -version核对工具链；用javap查看生成字节码，确认源代码与class对应。', JLS);
put('javase-2', 'IDEA提供编辑、调试与项目导航；Maven/Gradle定义可复现的构建。IDE可以调用构建工具，也有自己的运行配置，二者不一定自动一致。', '项目声明JDK、依赖和构建任务。¦构建工具解析依赖并编译、执行测试、打包。¦IDE调试启动特定classpath与配置，用断点观察参数和调用栈。', '# 两种构建体系分别示例，不是连续执行的同一项目\nmvn test\nmvn package\n./gradlew test\n./gradlew build', 'plaintext', 'IDE适合开发反馈，标准命令适合CI与环境复现；项目选定一种主要构建体系即可。', 'IDE运行成功可能依赖未提交资源或本地环境变量；Maven与Gradle的依赖配置不互相自动同步。', '在干净环境只用仓库文件执行构建；确认IDE与CLI使用同一JDK和激活配置。');
put('javase-3', '基本类型变量直接表达数字、布尔等值；引用变量表达对象引用，可为null。数组是固定长度、同元素类型的数据容器，创建后长度不变。', '声明确定编译期类型与允许操作。¦赋值可复制基本值或对象引用，复制引用不会复制对象。¦方法调用可以读取对象；包装类型拆箱前必须考虑null。', 'int[] a = {1, 2};\nint[] b = a;\nb[0] = 9;\nSystem.out.println(a[0]); // 9，共用数组\nLong id = null;\nif (id != null) System.out.println(id.longValue());', 'java', '字段类型按业务范围选择；未知id可为null，已验证必需id应明确拒绝缺失。', 'Java总是按值传参；传递引用的值不等于按引用传参。数组长度固定不表示元素不可变。', '比较复制数组和复制引用的结果；对null包装类型执行拆箱观察异常位置。', JLS);
put('javase-4', '运算符构成表达式，条件决定分支，循环重复行为，方法定义输入、输出和可复用步骤。业务代码的控制流应映射明确规则。', '先判断业务前置条件，再执行状态修改。¦循环处理集合时明确是否有副作用和停止条件。¦抽成方法后用参数表达依赖，返回值表达结果，异常表达无法正常完成。', 'static int total(List<Integer> quantities) {\n  int result = 0;\n  for (int q : quantities) {\n    if (q < 0) throw new IllegalArgumentException("quantity");\n    result = Math.addExact(result, q);\n  }\n  return result;\n}', 'java', '按业务步骤拆方法，使校验与修改顺序可读；很短逻辑无需为了层次拆成大量转发函数。', '==对引用一般比较对象身份，不是文本内容。循环里调用远程服务会把计算问题变成大量IO等待。', '测试空集合、负数与整数溢出；画出每个输入会进入哪个分支。', JLS);
put('javase-5', '封装让对象限制状态修改，继承建立子类型关系，多态让共同接口调用不同实现。真正有用的是稳定契约与可保护的不变量。', '调用者持有接口类型，不关心具体实现类。¦运行时分派到实际对象的方法实现。¦对象通过自身方法校验状态变化，避免外部绕过规则直接修改。', 'interface FeePolicy { int fee(int amount); }\nclass FreeFee implements FeePolicy {\n  public int fee(int amount) { return 0; }\n}\nFeePolicy policy = new FreeFee();\nSystem.out.println(policy.fee(100)); // 多态调用', 'java', '多种同类行为可替换时使用多态；继承只适用于能遵守父类型契约的关系。', '子类不能靠改变父类承诺获得“复用”；组合常能更清晰隔离变化。private字段也不自动保证并发安全。', '对所有实现运行同一契约测试；尝试非法状态修改，确认只能从受控方法进入。', JLS);
put('javase-6', '接口定义可调用契约，抽象类可包含共享状态和实现，内部类在外部类型范围内声明。非静态内部类可关联外部实例，静态嵌套类不需要外部实例。', '先定义调用者真正需要的少量方法。¦实现类或代理提供执行行为；抽象类可复用共同算法片段。¦选择嵌套类时明确是否需要持有外部对象，否则避免隐式引用。', 'interface EmployeeReader { String name(long id); }\nabstract class BaseReader {\n  protected void validate(long id) {\n    if (id <= 0) throw new IllegalArgumentException();\n  }\n}\nclass Holder { static class Item { long id; } }', 'java', '用接口划定可替换边界，用抽象类共享确有共同性的实现；简单数据类可独立或静态嵌套。', 'Mapper接口必须由MyBatis代理配合映射执行；内部类本身不提供线程隔离或业务权限。', '检查调用方依赖的类型与运行时实际类型；用反射观察非静态内部类构造器所需外部实例。', JLS);
put('javase-7', 'String不可变但变量可重新指向新字符串；java.time区分瞬间、日期、本地时间和时区；BigDecimal以十进制值及scale表示金额。', '文本修改通常产生或选择另一个字符串对象。¦记录全球时间点用Instant，展示时再应用ZoneId；LocalDateTime本身不含时区。¦金额运算明确精度、scale和舍入，比较数值可用compareTo。', 'BigDecimal a = new BigDecimal("1.0");\nBigDecimal b = new BigDecimal("1.00");\nSystem.out.println(a.equals(b)); // false：scale不同\nSystem.out.println(a.compareTo(b)); // 0：数值相同\nInstant now = Instant.now();\nSystem.out.println(now.atZone(ZoneId.of("Asia/Shanghai")));', 'java', '金额优先明确十进制规则；审计时间应选定存储与展示时区，测试可注入Clock。', 'new BigDecimal(0.1)携带二进制浮点近似；不可变String不意味着引用变量线程安全。', '测试1.0与1.00、跨时区展示和除不尽运算；确认数据库列精度与序列化保持预期。', JAVA);
put('javase-8', 'List保留顺序并允许重复，Set按相等规则去重，Map按键关联值；泛型在编译期表达元素类型，减少误用和强制转换。', '选集合前写出所需操作：有序遍历、去重还是按键查询。¦Hash型集合依赖equals与hashCode协作，排序型集合依赖比较关系。¦泛型检查类型，运行时通常存在类型擦除；并发修改需额外机制。', 'List<String> names = new ArrayList<>(List.of("A", "A", "B"));\nSet<String> unique = new HashSet<>(names);\nMap<Long,String> byId = Map.of(108L, "xiaozhi");\nSystem.out.println(unique.size()); // 2\nSystem.out.println(byId.get(108L));', 'java', '普通业务集合先选语义简单的标准实现；并发共享Map时再评估ConcurrentHashMap或更高层协调。', 'HashMap不保证业务遍历顺序；可变key字段改变hashCode会破坏检索；集合线程安全不等于组合操作原子。', '验证重复值、null与顺序契约；改变key的参与hash字段观察查找失败，说明不可变key价值。', JAVA);
put('javase-9', '异常是沿调用栈传播的失败信号。受检异常要求声明或处理，RuntimeException通常不强制声明；catch决定处理，finally用于可靠清理。', '失败点创建并抛出异常，正常执行在该点中断。¦调用栈寻找匹配catch；未处理继续向上传播。¦事务或Web框架在自身边界决定回滚与HTTP映射，资源用try-with-resources关闭。', 'try (InputStream in = Files.newInputStream(Path.of("input.txt"))) {\n  System.out.println(in.read());\n} catch (IOException ex) {\n  throw new UncheckedIOException("Read input failed", ex);\n}', 'java', '按调用者能否恢复选择处理边界，保留cause；业务拒绝与系统故障用不同错误契约。', 'catch后返回成功会隐藏失败。finally里抛异常可能遮蔽原异常；不是任何异常都会按默认事务规则回滚。', '模拟文件不存在，检查cause、资源关闭与外层错误；事务测试必须验证数据库状态而非只验证抛异常。', JLS);
put('javase-10', 'Lambda是函数式接口的实现表达式；Stream描述源数据的处理流水线。中间操作通常惰性，终止操作触发处理；它不替代业务事务与资源管理。', '从集合创建Stream，仅建立处理计划。¦filter保留匹配元素，map转换表示，终止操作收集或归约。¦避免共享副作用；并行执行还涉及线程资源和上下文传播。', 'List<String> activeNames = employees.stream()\n  .filter(e -> e.getStatus() == 1)\n  .map(Employee::getName)\n  .toList();\n// employees与Employee是业务已有类型', 'java', '集合转换用Stream通常清晰；复杂状态机或需要逐步异常处理的循环不必硬改流水线。', 'parallelStream并不自动保留请求ThreadLocal或事务上下文；toList返回的列表不可修改。', '只定义流水线但不终止，观察map副作用未执行；比较无副作用的循环与Stream结果一致性。', JAVA);
put('javase-11', 'BIO以阻塞读写为中心；NIO提供Buffer、Channel与Selector等能力；AIO通过完成回调或Future取得异步结果。TCP/UDP是网络协议，与这些IO编程接口不是同一分类。', 'Buffer有position、limit和capacity，写完需flip切到读取范围。¦非阻塞Channel没数据时不阻塞读取，Selector通知就绪事件。¦业务接到事件后仍可能调用阻塞JDBC；异步接口也要处理错误与取消。', 'ByteBuffer buffer = ByteBuffer.allocate(8);\nbuffer.putInt(108);\nbuffer.flip();\nSystem.out.println(buffer.getInt()); // 108\n// flip设置limit为已写位置，并把position归零', 'java', '高连接数服务器可使用成熟NIO框架；日常文件读取和业务HTTP应优先选择库，不必自制事件循环。', 'NIO连接器不等于Controller非阻塞。AIO也不保证底层所有操作都没有工作线程；具体实现需看平台。', '观察Buffer翻转前后position/limit；在NIO服务器中加入慢SQL，验证工作资源仍可能饱和。', JAVA);
put('javase-12', '反射在运行时检查类型与调用成员；注解携带元数据；枚举定义有限实例；代理把调用导向目标或增强逻辑。框架结合这些能力实现自动路由和事务。', '扫描器读取类与注解，建立Bean或路由元数据。¦动态代理实现接口，InvocationHandler收到方法与参数。¦代理按规则执行日志、事务或SQL，最后返回结果或传播异常。', 'interface Greeting { String hello(); }\nGreeting g = (Greeting) Proxy.newProxyInstance(\n  Greeting.class.getClassLoader(), new Class<?>[]{Greeting.class},\n  (proxy, method, args) -> "hello");\nSystem.out.println(g.hello());', 'java', '需要框架集成与动态行为时理解反射代理；普通静态调用无需反射。注解必须有读取者才能改变执行。', '示例只实现hello契约，通用代理还需处理Object方法等。访问控制和模块边界可能限制反射。', '打印proxy.getClass与method名称；移除处理注解的基础设施，确认注解自身不会执行事务。', JAVA);
put('javase-13', 'Thread提供执行路径；synchronized用对象监视器互斥且有可见性规则；Lock提供显式获取释放、尝试获取等能力。锁保护的是所有参与者共同遵守的状态边界。', '所有共享counter读写使用同一把锁。¦一个线程取得锁后更新，其他竞争者等待。¦释放后其他线程才能进入；显式Lock必须在finally释放。', 'Lock lock = new ReentrantLock();\nlock.lock();\ntry {\n  counter++; // 假设所有读写都遵守同一锁\n} finally {\n  lock.unlock();\n}', 'java', '一个JVM内复合状态更新可用锁；要跨实例保护数据库库存，应使用数据库条件更新等。', 'volatile只提供相应可见性与顺序规则，不把count++变原子。sleep不释放持有的监视器，也不提供同步语义。', '多个线程重复加一，join后检查最终值；使用相同锁与不同锁对比，定位互斥范围。', 'https://docs.oracle.com/javase/specs/jls/se21/html/jls-17.html');
put('javase-14', '线程池管理任务执行资源，CAS比较期望值后条件写入，AQS提供许多同步器的状态与等待队列基础，JUC集合这些工具。原子单变量不等于整个业务原子。', '任务提交后按池与队列策略执行、排队或拒绝。¦CAS发现值已改变时失败，调用者可重试或返回冲突。¦AQS类同步器依据许可或锁状态阻塞与唤醒等待者，具体语义由同步器定义。', 'ThreadPoolExecutor pool = new ThreadPoolExecutor(\n  4, 4, 0, TimeUnit.SECONDS,\n  new ArrayBlockingQueue<>(100),\n  new ThreadPoolExecutor.AbortPolicy());\nAtomicInteger count = new AtomicInteger();\npool.submit(count::incrementAndGet);\npool.shutdown();', 'java', 'CPU和IO任务按资源分开限额；有界队列使过载可见。单计数用原子类，多个字段不变量常需锁或事务。', 'shutdown不等待所有任务完成。队列、最大线程、拒绝策略共同决定行为；更多线程不能创造更多数据库能力。', '阻塞工作线程后继续提交，观察队列100满时拒绝；等待任务完成后检查计数与关闭行为。', JAVA);
put('javase-15', '类加载使类型可执行，GC按可达性处理对象生命周期，调优解释资源与延迟证据。这些JVM行为影响性能，但不改变业务必须满足的正确性。', '应用加载字节码并建立类型关系。¦每次请求分配DTO、字符串等对象，仍被强引用的对象通常不能被回收。¦观察分配、存活集与GC时间，区分短期分配压力和长期对象保留。', '# JDK21示例启动参数\njava -Xms512m -Xmx512m -Xlog:gc*:file=gc.log app.jar\n# 若JAR可执行，实际启动应加-jar：\njava -Xms512m -Xmx512m -Xlog:gc*:file=gc.log -jar app.jar', 'plaintext', '请求延迟或内存异常有证据时分析JVM；正常系统不应因背到某参数就反复改GC配置。', '所有暂停不都来自GC；内存泄漏是无用对象被保留，不等于堆使用量每次暂时上升。', '对齐GC日志和请求p99，查看一次GC后存活占用是否持续增长；必要时用堆转储看保留路径。', JAVA);

put('web-1', '浏览器提供DOM、JavaScript与网络环境，Vue管理响应式状态与组件，渲染把状态转换为界面。三者不是每次请求依次进入的三台服务器。', '用户输入更新form状态。¦点击事件发起API，成功结果更新响应式数据。¦Vue安排界面更新，列表是否重新查询由业务逻辑决定。', 'const rows = ref([]);\nasync function refresh() {\n  rows.value = (await axios.get("/employees")).data;\n}', 'javascript', '多状态交互适合组件框架；简单静态页不必引入Vue。服务端仍独立执行校验与授权。', '页面上显示成功不能证明数据库持久化。DOM更新批次与响应收到时间也不同。', '新增后刷新页面再查询；检查Network请求、返回数据和DOM三处是否一致。', 'https://vuejs.org/guide/essentials/reactivity-fundamentals.html');
put('web-2', 'Ajax泛指不整页跳转的异步交互；Fetch是浏览器API，Axios是客户端库。它们产生HTTP请求，JSON序列化、超时和错误处理取决于具体API。', '把URL、Method、Header与Body明确传给客户端。¦等待响应时处理网络异常与HTTP状态，二者不能混为一类。¦读JSON后按业务契约决定提示和状态更新。', 'const r = await fetch("/employees", {\n  method: "POST", headers: {"Content-Type":"application/json"},\n  body: JSON.stringify({username:"xiaozhi"})\n});\nif (!r.ok) throw new Error(`HTTP ${r.status}`);\nconst result = await r.json();', 'javascript', '简单浏览器请求可用Fetch；已有Axios工程继续使用其统一配置与拦截器，不需同时维护两套。', 'Fetch收到404通常仍resolve；Axios错误策略可被validateStatus改变。两者均不能凭超时断定服务器未执行。', '分别模拟HTTP409和断网，验证错误分支不同；查看实际Content-Type和正文。', 'https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch');
put('web-3', 'URL指定方案、主机、端口、路径、查询等定位信息；HTTP规定方法、请求与响应语义；HTTPS通过TLS保护HTTP。JSON只是常见内容格式。', '服务端按Method和路径等条件找到操作。¦Header说明媒体类型、缓存、认证等元信息，Body承载内容。¦状态码表达HTTP结果，响应内容表达业务数据。', 'GET /employees/108?fields=name HTTP/1.1\nHost: api.example.test\nAccept: application/json\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n{"id":108,"name":"小智"}', 'plaintext', '先定义方法、资源和错误语义再写Controller；HTTPS用于保护传输，业务权限另外设计。', 'URL片段#通常不发给服务器。POST不等于新增，PUT的幂等语义也不意味着服务端随便实现都正确。', '从接口文档还原完整请求，用Network核对Method、URL、Header、Body与状态。', 'https://www.rfc-editor.org/rfc/rfc9110.html');
put('web-4', 'Cookie是浏览器按范围发送的HTTP状态数据；Session通常是服务端保存的会话状态，由Cookie中的ID关联；状态码描述HTTP结果，不是会话或业务code。', '登录成功后服务器建立会话并Set-Cookie。¦后续浏览器按Domain、Path、Secure与SameSite等规则附带Cookie。¦服务器查会话并验证授权，然后返回200、401、403等状态。', 'Set-Cookie: sid=<opaque-id>; HttpOnly; Secure; SameSite=Lax\n\nCookie: sid=<opaque-id>\n\nHTTP/1.1 403 Forbidden\n{"message":"没有此操作权限"}', 'plaintext', '浏览器应用可采用服务端会话；多实例时需共享或一致路由，选择依威胁模型和产品需求。', 'HttpOnly防脚本读取，不防所有CSRF。Session不是总在单机内存；JWT与Cookie也不是互斥选项。', '在浏览器存储与请求头确认Cookie发送范围；测试未登录401、已登录无权限403与登出后失效。', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Cookies');
put('web-5', 'Servlet是Java Web处理请求的规范组件；Tomcat实现Servlet容器并提供HTTP连接处理。Spring MVC的DispatcherServlet运行在容器中。', '连接器读取HTTP并构造请求响应对象。¦容器按URL映射进入Filter链与Servlet。¦Servlet可能被多个线程并发调用，因此请求数据应局部保存。', 'class HelloServlet extends HttpServlet {\n  protected void doGet(HttpServletRequest req,\n      HttpServletResponse resp) throws IOException {\n    resp.setContentType("text/plain;charset=UTF-8");\n    resp.getWriter().write("hello");\n  }\n}', 'java', '理解Servlet能解释容器、Filter与MVC的边界；Spring项目通常无需为每个业务手写Servlet。', '示例需要Jakarta Servlet依赖与注册。内嵌Tomcat不是唯一服务器选项，WebFlux也不是此Servlet调用链。', '用Servlet映射验证请求进入点；并发请求观察同一实例执行而不是每请求创建Servlet。', 'https://tomcat.apache.org/tomcat-10.1-doc/');
put('web-6', 'Filter围绕Servlet请求链运行；Listener观察容器、会话等生命周期事件。Filter可对每请求处理，启动监听器不是每请求一层。', '容器依配置顺序执行Filter，doFilter进入下一段。¦Filter用finally释放本次请求上下文，失败也应覆盖。¦Listener在相应事件发生时调用，不替代请求拦截。', 'public void doFilter(ServletRequest req, ServletResponse res,\n    FilterChain chain) throws IOException, ServletException {\n  long start = System.nanoTime();\n  try { chain.doFilter(req, res); }\n  finally { recordDuration(System.nanoTime() - start); }\n}', 'java', '入口请求ID、编码、Servlet安全链可用Filter；MVC handler相关逻辑可用Interceptor，需明确异常处理位置。', 'MVC Advice一般不直接覆盖进入DispatcherServlet前的Filter错误。Filter顺序会改变认证、CORS与日志行为。', '在两个Filter、Servlet、finally分别打印步骤，验证正常与异常调用顺序及清理。', 'https://jakarta.ee/specifications/servlet/');
put('web-7', 'DispatcherServlet是MVC前端控制器；HandlerMapping查询能够处理当前请求的handler及拦截链。它不是Service工厂，也不在此执行业务SQL。', '启动时@RequestMapping等映射被注册。¦请求到来后按照路径、方法、媒体类型等条件匹配。¦命中的handler交给适配器；MVC拦截器preHandle在调用前执行。', '@RestController\n@RequestMapping("/employees")\nclass EmployeeController {\n  @GetMapping("/{id}")\n  EmployeeVO get(@PathVariable long id) { return service.get(id); }\n}', 'java', '从请求定位方法时先组合类级与方法级映射；应用代码主要维护映射，不需要重写DispatcherServlet。', 'Method和Path是主要条件但不是全部；找到handler不代表参数解析、认证或业务一定成功。', '分别请求正确路径、错误Method与不支持媒体类型，观察404、405、415等失败位置。', MVC);
put('web-8', 'HandlerAdapter按handler种类组织调用；参数解析器根据注解和类型取得数据。Body、Path、Query是HTTP中不同位置，不能凭字段名互相替代。', 'MVC取得handler签名并选择参数解析器。¦路径占位符绑定@PathVariable，查询或表单绑定@RequestParam。¦@RequestBody由消息转换器读取正文，准备完成后调用Controller。', '@PutMapping("/employees/{id}")\nEmployeeVO edit(@PathVariable long id,\n    @RequestParam boolean notify,\n    @Valid @RequestBody EmployeeEditDTO dto) {\n  return service.edit(id, dto, notify);\n}', 'java', '按接口契约选数据位置：资源ID常在Path，筛选分页在Query，复杂写入在Body。', '查询参数不会自动成为JSON正文；Body缺失、类型转换错误可在Controller执行前拒绝。', '发送id非数字、notify缺失、非法JSON三组请求，确认方法有没有执行及错误响应。', 'https://docs.spring.io/spring-framework/reference/web/webmvc/mvc-controller/ann-methods.html');
put('web-9', 'JSP是服务端模板技术，JSTL提供常见模板标签，EL表达式读取模型数据。它们输出HTML，与@RestController返回JSON的表示方式不同。', 'Controller返回视图名并放入模型属性。¦视图解析器找到模板，模板读取模型字段。¦服务器生成HTML发给浏览器，不要求前端再把JSON渲染成列表。', '@Controller\nclass PageController {\n  @GetMapping("/employees/page")\n  String page(Model model) {\n    model.addAttribute("employees", service.list());\n    return "employees/list";\n  }\n}', 'java', '传统服务端渲染项目按现有模板体系维护；Vue前后端分离API不必再给每个接口加JSP。', '模板部署和Servlet版本要兼容。@RestController返回employees/list字符串通常写入正文，不选择该模板。', '检查Content-Type与响应内容，确认返回HTML；验证模板中的输出编码与敏感字段控制。');
put('web-10', 'MVC拆分模型、视图与控制职责；前后端分离以API契约连接独立展示和业务；JSON/XML是表示格式。Service/Mapper分层是应用架构，不能直接等同MVC定义。', '业务模型与规则形成后端用例。¦Controller将HTTP输入映射到用例并选择结果表示。¦视图可由服务器模板或前端组件产生，数据格式由接口协商。', '同一用例：查询员工108\nHTML客户端 → 页面Controller → 模板\nJSON客户端 → REST Controller → EmployeeVO → JSON\n共享业务：EmployeeService.get(108)', 'plaintext', '按客户端与部署需要选择渲染方式；无独立前端需求时无需强制分离部署。', '返回JSON不等于实现了良好REST设计；XML也可承载同样业务，格式不决定权限或事务。', '给同一Service准备两个展示入口，验证业务规则与表示格式解耦。', MVC);
put('web-11', '表单常用urlencoded或multipart编码；文件上传通常用multipart；下载是带媒体类型和可选Content-Disposition的响应。二进制不是普通JSON字段。', '浏览器FormData包含字段与文件，由客户端生成multipart边界。¦服务器校验大小、真实内容与权限，交给存储。¦下载按授权读取并流式返回，控制文件名、缓存与范围。', 'const body = new FormData();\nbody.append("avatar", file);\nawait fetch("/employees/108/avatar", {method:"POST", body});\n// 不手动设置Content-Type，浏览器需补multipart boundary', 'javascript', '小文件同步上传可以；大文件可用授权直传和异步处理，避免应用充当全部流量中转。', '扩展名和客户端Content-Type不可信。上传返回URL后也要控制下载权限和对象生命周期。', '测试过大、伪造类型、无权限、断传等路径；观察内存或磁盘是否随上传规模无界增长。', 'https://developer.mozilla.org/en-US/docs/Web/API/XMLHttpRequest_API/Using_FormData_Objects');
put('web-12', '注入让输入改变指令，XSS让不可信内容作为脚本运行，CSRF利用浏览器凭据发送非意愿请求，越权绕过资源权限。CORS是浏览器跨源访问策略，不是身份认证。', '服务器参数化SQL并按资源检查操作者。¦页面按输出位置编码文本，避免把任意内容当HTML。¦Cookie认证考虑CSRF保护；跨源请求按精确来源和凭据策略配置。', '// Vue文本插值按文本展示，不使用v-html渲染不可信值\n// 服务端伪代码：\nEmployee e = repository.get(id);\nauthorizer.requireCanEdit(operatorId, e);\nrepository.update(validatedInput);', 'java', '针对威胁选择控制，不应把“开CORS”当联调万能解；资源授权必须在服务端。', '浏览器拦读取不等于请求一定没到服务器。允许Origin与允许操作是两个独立判断。', '绕过UI直接改其他员工id，期望403；发送攻击文本与跨源Cookie请求验证相应保护。', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CORS');

put('sql-1', 'DDL定义结构，DML修改数据，DQL常指查询，DCL管理授权，TCL控制事务。这是用途分类，数据库实际隐式提交与语法规则比标签更重要。', '迁移阶段执行CREATE/ALTER等结构SQL。¦业务执行SELECT、INSERT、UPDATE、DELETE；权限管理执行授权命令。¦BEGIN/COMMIT/ROLLBACK控制支持事务的操作，注意DDL隐式提交边界。', 'START TRANSACTION;\nINSERT INTO employee(id,username) VALUES(108,"xiaozhi");\nROLLBACK;\nSELECT * FROM employee WHERE id=108; -- 不应有新行', 'sql', '用分类定位哪个流程负责SQL；业务开发不应使用拥有全局DDL权限的数据库账号。', 'MySQL许多DDL会隐式提交，不可把ALTER混入普通DML事务并期待一起回滚。', '在隔离测试库分别验证DML回滚与DDL边界，记录实际MySQL8.4行为。', 'https://dev.mysql.com/doc/refman/8.4/en/implicit-commit.html');
put('sql-2', 'WHERE筛行，JOIN按关系组合行，GROUP BY分组，聚合对组计算，HAVING筛聚合结果。执行计划可重排物理步骤，但语义必须保留。', '员工与部门按department_id连接，一对多会增加结果行数。¦按部门分组，再COUNT员工；LEFT JOIN保留无员工部门。¦选择COUNT(e.id)避免把无匹配的外连接占位行算为一个员工。', 'SELECT d.id, d.name, COUNT(e.id) AS employees\nFROM department d\nLEFT JOIN employee e ON e.department_id=d.id\nGROUP BY d.id,d.name\nHAVING COUNT(e.id)>=0;', 'sql', '聚合应尽量在数据库完成合理过滤，而不是取全表回Java；小集合内存统计仍可合理。', '把WHERE e.status=1写在外连接后可能排除无员工部门，可按需求将条件移到ON。COUNT(*)与COUNT(nullableColumn)不同。', '准备空部门、一员工部门、多员工部门，手算与查询结果对照。', MYSQL);
put('sql-3', '表设计是把业务实体、关系与不变量转换为列、键、约束；范式减少重复引发的更新异常，并不要求任何业务都无限拆表。', '先写员工、部门、角色的身份与基数关系。¦确定主键、必填、唯一性和字段类型，敏感字段控制保存形式。¦依据查询模式增加索引，对冗余字段定义更新责任。', 'CREATE TABLE employee(\n  id BIGINT PRIMARY KEY AUTO_INCREMENT,\n  username VARCHAR(50) NOT NULL,\n  department_id BIGINT,\n  UNIQUE KEY uk_username(username),\n  KEY ix_department(department_id)\n);', 'sql', 'username唯一和部门归属属于数据约束；为报表适当冗余时必须说明权威来源与同步方式。', '是否区分大小写由排序规则等决定；Java查重不能替代数据库唯一性，NULL与唯一键语义也要验证。', '插入同名、不同大小写和缺必填值；检验排序规则与实际业务唯一性是否一致。', MYSQL);
put('sql-4', '索引是按键组织的访问结构。MySQL优化器选择计划，EXPLAIN展示计划，EXPLAIN ANALYZE执行并展示实际统计；后者不是只读“解释而不运行”。', 'WHERE与JOIN条件提供候选访问路径。¦复合索引按列顺序组织，是否能有效使用取决于谓词、排序与成本。¦读取所需列可能回表；覆盖索引可减少额外行访问。', 'CREATE INDEX ix_status_id ON employee(status,id);\nEXPLAIN SELECT id FROM employee WHERE status=1 ORDER BY id LIMIT 20;\n-- 测试环境：ANALYZE会实际执行查询\nEXPLAIN ANALYZE SELECT id FROM employee WHERE status=1 ORDER BY id LIMIT 20;', 'sql', '对高频慢查询结合真实数据设计索引；很小表扫描未必差，不必看到ALL就认定故障。', '索引提高部分读取速度但增加写成本；估计行数不等于实际行数，统计信息可能过时。', '比较改前改后的实际扫描行数、耗时和写入成本，使用相同数据与请求条件。', 'https://dev.mysql.com/doc/refman/8.4/en/explain.html');
put('sql-5', '事务把支持它的一组操作放到提交边界；ACID分别涉及原子、约束一致、隔离与耐久。隔离级别控制并发可见性，不自动把所有业务竞争串行。', '同一Connection开始事务并执行相关DML。¦InnoDB按隔离与语句类型决定版本或锁读取。¦COMMIT完成边界，失败按规则ROLLBACK；外部短信并不在此数据库事务内。', 'START TRANSACTION;\nINSERT INTO employee(username) VALUES("xiaozhi");\nINSERT INTO employee_role(employee_id,role_id) VALUES(LAST_INSERT_ID(),2);\nCOMMIT;', 'sql', '多次写入需共同成功时设置清晰业务事务；只读查询也需按一致性目标选择事务范围。', 'MySQL8.4 InnoDB默认隔离为REPEATABLE READ，但项目可改。耐久受配置、复制与故障模型影响，不能笼统承诺绝无数据丢失。', '在第二次写入注入失败，检查第一行是否回滚；两个连接推演快照与提交可见性。', 'https://dev.mysql.com/doc/refman/8.4/en/innodb-transaction-isolation-levels.html');
put('sql-6', 'MVCC用版本支持一致性读取，锁协调冲突更新。普通一致性SELECT与SELECT FOR UPDATE的锁定读不同；正确扣库存可把检查与修改合成条件UPDATE。', '两个请求都读到stock=1，并不保证二者随后都能安全减一。¦UPDATE stock=stock-1 WHERE stock>0在数据库执行条件写。¦检查受影响行数，失败不创建成功订单；多表组合放事务。', 'UPDATE inventory SET stock=stock-1\nWHERE product_id=8 AND stock>0;\n-- rows=1：本次扣减成功\n-- rows=0：未满足库存条件\n-- 订单写入与扣减需放在共同事务边界', 'sql', '简单竞争写优先利用条件更新；复杂读取后多字段变更可考虑锁定读或版本校验。', '锁范围依索引、语句与隔离变化；加事务但仍先查后无条件写，可能依然违背业务不变量。', '两个数据库连接并发执行扣减，断言stock不为负且成功次数符合初始库存；观察锁等待和死锁日志。', 'https://dev.mysql.com/doc/refman/8.4/en/innodb-locking.html');
put('sql-7', '视图封装查询，存储过程在数据库执行一组语句，触发器随指定表事件自动运行。三者使逻辑进入数据库，但不会自动降低复杂度。', '查询视图时数据库展开或按规则执行对应查询。¦调用存储过程按其控制流执行数据库逻辑。¦表事件触发额外操作，这些副作用要纳入事务、权限和性能分析。', 'CREATE VIEW active_employee AS\nSELECT id,username FROM employee WHERE status=1;\nSELECT * FROM active_employee;\n-- 视图不是默认缓存，后续查询仍需访问底层数据', 'sql', '稳定共享查询可封装视图；复杂业务通常留在可测试服务中，是否用过程/触发器取决于现有体系和运维能力。', '视图不等于物化缓存。触发器隐藏在Java调用栈之外，可能改变行数、锁和耗时。', '变更底层表后查询视图，确认更新可见；排错同时检查SHOW TRIGGERS与过程定义。', MYSQL);
put('sql-8', 'SQL优化是减少不必要工作并验证收益，证据包括扫描行、返回行、执行时间、锁与网络；不只是改语法或添加缓存。', '先取得慢查询及真实参数和数据规模。¦比较计划与实际执行，区分扫描、排序、锁等待或大结果传输。¦改SQL、索引或访问方式后，用同一负载验证端到端及写入代价。', 'SELECT id,username FROM employee\nWHERE id>108 AND status=1\nORDER BY id LIMIT 20;\n-- 游标分页：最后一行id作为下一页afterId', 'sql', '连续向后浏览可用游标分页降低深OFFSET工作；需要任意跳页时应明确产品和性能取舍。', 'id游标必须与过滤和稳定排序兼容；不能直接代替按姓名排序的分页，也不能保证任意并发更新下固定快照。', '对比OFFSET100000和游标分页的实际扫描、耗时与结果语义；覆盖删行、增行边界。', MYSQL);
put('sql-9', '复制把变更传播到副本，读写分离将读路由到不同节点，分片把数据按规则拆到多个节点。这三件事目标不同：冗余、读容量与数据容量。', '主库提交后副本接收并应用日志，可能落后。¦路由器决定读主库或副本，写后读需一致性策略。¦分片按key定位数据，跨片聚合与事务需要额外设计。', '创建员工：write → primary\n紧接查询108：read → primary（本会话一致性策略）\n普通列表：read → replica（允许短暂滞后）\n分片示例：shard = hash(tenantId) % shardCount', 'plaintext', '先有明确副本读取与容量需求再引入；单库可满足时不应提前增加分片迁移成本。', '副本不是默认实时最新。简单取模扩分片会迁移大量数据；复制也不是备份的完全替代。', '人工暂停副本应用，验证写后读行为与延迟告警；分片测试覆盖跨租户查询和迁移。', 'https://dev.mysql.com/doc/refman/8.4/en/replication.html');
put('sql-10', 'Redis擅长按key快速操作多种内存数据结构；MongoDB按文档组织数据与查询；Elasticsearch按倒排索引检索。它们不是同一种NoSQL替换按钮。', '按访问模式选择权威存储或派生存储。¦关系数据提交后，可异步构建Redis缓存或搜索索引。¦读取按一致性要求选来源，不用派生搜索结果替代权限裁决。', 'MySQL：employee表是此案例权威记录\nRedis：employee:108 → 展示摘要，带TTL\nMongoDB：可存独立文档型业务（并非本例必需）\nElasticsearch：姓名关键词 → 员工文档命中', 'plaintext', '需要特定数据模型或检索能力时增加专用引擎；只做简单员工CRUD可先使用MySQL。', 'Redis支持持久化但此案例仍把它作为可重建缓存；MongoDB也有事务和索引，NoSQL不等于无需设计。', '停止缓存和索引，验证权威写入与授权仍可正确工作；测量派生数据延迟与恢复。');

put('engineering-1', 'Maven坐标标识构件，仓库提供下载位置，生命周期阶段组织构建目标。插件执行具体工作；执行后阶段会包含之前阶段的已绑定目标。', 'pom声明依赖坐标及版本，仓库解析相应构件。¦compile编译，test执行测试，package生成制品，verify执行绑定的后续检查。¦install写入本地仓库，deploy发布仓库，不等于部署应用服务。', '<dependency>\n  <groupId>org.junit.jupiter</groupId>\n  <artifactId>junit-jupiter</artifactId>\n  <version>5.11.4</version>\n  <scope>test</scope>\n</dependency>\n<!-- 示例固定版本；实际以项目兼容性清单为准 -->', 'xml', '用统一构建命令交付可复现制品；版本固定或BOM管理，避免依赖漂移。', 'mvn deploy默认指构件仓库发布，不是启动远端应用。依赖scope影响classpath和传递，不只是备注。', 'mvn dependency:tree检查最终版本；在干净环境mvn verify并比较制品与测试结果。', 'https://maven.apache.org/guides/introduction/introduction-to-the-lifecycle.html');
put('engineering-2', 'dependency提供库，plugin执行构建；聚合modules统一构建，parent继承配置；BOM在dependencyManagement管理一组版本而不自动引入全部库。', '父POM提供共享配置，子模块按规则继承。¦聚合POM收集模块并按依赖关系构建。¦导入BOM后，子模块仍声明所需dependency，最终版本由管理和覆盖规则决定。', '<dependencyManagement><dependencies>\n  <dependency>\n    <groupId>com.example</groupId><artifactId>platform-bom</artifactId>\n    <version>1.0.0</version><type>pom</type><scope>import</scope>\n  </dependency>\n</dependencies></dependencyManagement>\n<!-- com.example坐标是教学占位，需替换为项目真实BOM -->', 'xml', '多模块或大量依赖需要集中版本约束；单模块不必为了“架构”过早拆聚合。', '父子关系与聚合关系可分别存在。导入BOM不能凭空创建其依赖，也不能保证任意覆盖版本都兼容。', '用help:effective-pom和dependency:tree检查继承、版本与实际引入项。', 'https://maven.apache.org/guides/introduction/introduction-to-dependency-mechanism.html');
put('engineering-3', 'Gradle根据任务及依赖图执行构建，插件建立Java等任务，Wrapper记录构建工具分发版本。构建结果仍取决于JDK、依赖与脚本。', '插件建立compileJava、test等任务。¦任务依赖决定执行顺序，输入输出声明支持增量或缓存。¦Wrapper统一Gradle版本，工具链配置统一JDK需求。', 'plugins { id("java") }\njava { toolchain { languageVersion.set(JavaLanguageVersion.of(21)) } }\ntasks.test { useJUnitPlatform() }\n// Kotlin DSL；还需按项目声明JUnit依赖与仓库', 'plaintext', '已有Gradle项目使用Wrapper；不用因偏好同时维护等价Maven脚本。', '增量和构建缓存需要正确声明输入；缓存命中不是测试覆盖生产环境的证明。', '执行./gradlew clean test，再观察输入变化后的任务状态；核对工具链实际JDK。', 'https://docs.gradle.org/current/userguide/java_plugin.html');
put('engineering-4', '项目结构帮助定位职责，规范约束命名、错误处理与依赖方向。目录只是可见组织方式，真正边界由调用与行为决定。', 'Controller只接协议与调业务，Service集中不变量。¦Mapper隐藏数据库执行，DTO/VO控制边界数据。¦模块按业务内聚，公共代码只抽真正稳定且复用的契约。', 'employee/\n  EmployeeController.java   # HTTP契约\n  EmployeeService.java      # 创建/修改用例\n  EmployeeMapper.java       # SQL访问\n  EmployeeDTO.java          # 输入\n  EmployeeVO.java           # 展示', 'plaintext', '随着项目规模按领域组织并限制依赖；很小项目无需机械制造每项接口与实现类。', '包名分层不会阻止Controller直连Mapper；需要评审或依赖约束检查守住规则。', '检查新增用例能否由HTTP与导入复用Service，并且不能绕过权限或事务。');
put('engineering-5', '配置描述环境连接与运行参数，环境隔离限制数据与权限混用。秘密不应因方便而和代码一起发布。', '区分代码、非敏感配置与秘密来源。¦部署时注入端口、数据库地址和凭据，启动验证必需值。¦测试与生产拥有独立账号、数据和权限，变更可追踪。', 'spring:\n  datasource:\n    url: ${DB_URL}\n    username: ${DB_USER}\n    password: ${DB_PASSWORD}\n# 环境变量由部署环境提供，不写真实秘密', 'yaml', '任何可部署应用都应明确环境；本地可简单配置，但上线前必须避免误连生产。', '环境变量本身也需保护；Profile文件名不提供安全权限。配置缺省值可能掩盖缺失。', '清除必需环境变量验证启动失败信息；确认测试数据库地址及账号无法访问生产。');
put('engineering-6', '日志记录离散运行事件，级别区分调试与故障，结构字段支持检索与关联。业务审计与技术日志目的不同，不能相互完全替代。', '入口产生或取得可信requestId，沿调用关联。¦记录操作、结果与耗时，异常保留cause和栈。¦脱敏敏感数据并控制级别、采样与存储周期。', 'log.info("employee_created requestId={} employeeId={} operatorId={}",\n    requestId, employeeId, operatorId);\n// 不记录password、token、完整身份证', 'java', '为关键状态变化与失败提供可诊断事件；高频细节可按需采样，避免全量打印对象。', '异步线程不自动继承日志上下文；日志系统故障、时间偏差与丢失影响证据完整性。', '用一个requestId检索入口到SQL/事件，模拟异常确认栈可见且没有敏感字段。');
put('engineering-7', 'YAML表达层次和类型，properties以键值表达配置；框架把键解释成属性并转换类型。文件格式不会自动确保键有效或配置被采用。', '读取配置源并按优先级合并。¦层次键或点分键对应目标属性。¦绑定时类型转换与校验，错误或未识别键需被发现。', '# application.properties\napp.invite-timeout=2s\napp.max-upload-size=10MB\n# YAML等价表达：\n# app:\n#   invite-timeout: 2s\n#   max-upload-size: 10MB', 'plaintext', '选团队一致格式；大量业务配置可用@ConfigurationProperties集中绑定和验证。', 'YAML缩进或特殊字符串会改变解析；属性存在文件里不证明目标组件读取了它。', '通过配置绑定测试断言最终值，显式设置一个值并确认运行行为变化。');
put('engineering-8', 'Lombok在编译阶段生成常见成员，MapStruct生成类型映射代码，BeanUtils按可读写属性运行时复制。它们降低重复，不自动执行授权与业务规则。', 'DTO到Entity先明确允许从客户端输入的字段。¦MapStruct可显式忽略敏感目标字段，生成代码供查看。¦BeanUtils复制同名属性通常是浅层行为，复杂差异需手动处理。', '@Mapper\ninterface EmployeeConverter {\n  @Mapping(target="id", ignore=true)\n  @Mapping(target="passwordHash", ignore=true)\n  Employee toEntity(EmployeeDTO dto);\n}\n// org.mapstruct.Mapper，不是MyBatis @Mapper', 'java', '字段映射多且稳定时使用MapStruct；简单安全映射可直接构造对象，不必依赖自动复制。', '两种@Mapper来自不同包。Lombok的equals/toString可能包含敏感或可变字段，必须审查生成行为。', '查看生成源码并测试忽略字段；客户端传id或权限时确认不能覆盖Service决定的值。', 'https://mapstruct.org/documentation/stable/reference/html/');
put('engineering-9', 'OpenAPI是HTTP接口的机器可读契约，Swagger生态和Knife4j提供查看、生成和调试体验。文档UI不是业务执行框架。', '定义路径、方法、参数与Schema。¦明确成功和400/401/403/409等失败响应。¦消费者依契约联调，修改时评估兼容性而非只更新截图。', 'paths:\n  /employees:\n    post:\n      summary: 新增员工\n      responses:\n        "201": {description: 已创建}\n        "409": {description: 用户名冲突}', 'yaml', '多人联调、外部API或自动客户端生成需要契约；小型内部接口也应至少明确请求和错误格式。', '示例只是paths片段，还需openapi、info及完整Schema。自动扫描注解可能遗漏业务条件。', '从文档还原请求执行成功与失败用例，比较实际响应字段与Schema。', 'https://spec.openapis.org/oas/latest.html');
put('engineering-10', 'Postman和Apifox构造HTTP请求并组织环境、断言、接口协作。它们是客户端验证工具，不代替服务端测试与数据库状态确认。', '为环境定义baseUrl和测试身份。¦显式发送合法、缺认证、非法参数、冲突请求。¦断言状态与内容，并对写操作确认后续查询结果。', '用例1：POST /employees，缺token → 401\n用例2：合法token，username空 → 400\n用例3：新username → 201\n用例4：重复username → 409\n用例5：GET新id → 内容匹配', 'plaintext', '联调和接口回归适合工具集合；底层并发与事务规则还需真实数据库集成测试。', '分享集合时检查秘密；正确调用测试环境并不证明代理、生产配置相同。', '导出无秘密集合由他人执行，确认断言能在故意返回错误结果时失败。');

put('spring-1', 'IoC把对象创建组装控制交给容器；DI是把依赖提供给对象的方法；Bean是由容器管理的对象。默认作用域与线程安全是不同维度。', '扫描或@Bean注册对象定义。¦创建对象时解析构造器依赖，再完成生命周期与可能的代理。¦请求调用已经组装的Bean，通常不会每次重新装整个应用。', '@Service\nclass EmployeeService {\n  private final EmployeeMapper mapper;\n  EmployeeService(EmployeeMapper mapper) { this.mapper=mapper; }\n}', 'java', '用构造器表达必需依赖并便利测试；不是所有临时DTO都需成为Bean。', '默认singleton表示每容器该Bean定义一个实例，不保证共享字段安全；请求参数不要存Service字段。', '获取两次同名singleton Bean比较身份；并发请求验证状态保存在局部变量而非实例字段。', 'https://docs.spring.io/spring-framework/reference/core/beans.html');
put('spring-2', 'Bean生命周期包括实例化、依赖填充、初始化及销毁，后处理器可在过程中包装代理。一个对象已构造不代表完整代理与资源已就绪。', '容器创建实例并注入依赖。¦初始化回调执行，BeanPostProcessor可影响返回给调用方的对象。¦上下文关闭时执行受支持的销毁回调，释放连接池或工作资源。', '@Component\nclass Worker {\n  @PostConstruct void init() { /* 检查配置 */ }\n  @PreDestroy void close() { /* 关闭自己拥有的资源 */ }\n}', 'java', '初始化轻量资源、验证配置和关闭资源时使用生命周期；慢业务启动任务需考虑就绪与重试。', '原型Bean销毁不会由容器像singleton一样统一跟踪。@PostConstruct中的自身调用不能假定经过完整事务代理。', '记录构造、注入、初始化、获取Bean与关闭事件；用代理类型与失败测试验证实际执行。', 'https://docs.spring.io/spring-framework/reference/core/beans/factory-nature.html');
put('spring-3', 'BeanFactory提供Bean获取等核心容器能力；ApplicationContext在其基础上增加应用事件、资源解析和常见集成。它们管理对象，不保存业务表数据。', '注册配置形成Bean定义。¦Context刷新初始化基础设施与常见singleton。¦调用getBean获取管理对象，关闭Context释放受管理资源。', 'try (var context = new AnnotationConfigApplicationContext(AppConfig.class)) {\n  EmployeeService service = context.getBean(EmployeeService.class);\n  // 调用容器提供的对象，可能是代理\n}', 'java', '普通Boot应用由启动器管理Context；手动Context适合小实验，不必业务方法反复new容器。', '多个Context有作用域与父子可见性；相同类在不同容器不意味着同一个singleton。', '创建两个独立Context比较Bean实例；发布事件验证监听器属于哪个容器。', 'https://docs.spring.io/spring-framework/reference/core/beans/context-introduction.html');
put('spring-4', 'AOP把横切行为包在匹配方法调用周围，事务增强调用事务管理器。模块化限制职责依赖，AOP本身不是固定业务层。', '容器为需增强Bean创建代理。¦外部调用先进入代理，增强选择开始或加入事务。¦目标正常返回后提交；失败依据规则回滚再传播。', '@Service\nclass EmployeeService {\n  @Transactional(rollbackFor=Exception.class)\n  public void create(EmployeeDTO dto) {\n    mapper.insert(toEmployee(dto));\n    roleMapper.grantDefaultRole();\n  }\n}', 'java', '日志、事务等重复技术行为适合增强；关键业务规则仍应在可读用例内，不藏在任意切面。', '默认代理模式this调用绕过代理。默认RuntimeException/Error回滚，受检异常规则可配置；可见性行为随版本与代理方式变化。', '从另一Bean调用，第二SQL故意失败，断言第一SQL回滚；对比this调用和外部代理调用。', TX);
put('spring-5', 'Spring MVC是Servlet Web框架，协调handler映射、适配、参数、返回值与异常。Service和Mapper可由MVC调用，但不因此成为MVC框架内部组件。', 'DispatcherServlet通过映射找到handler。¦拦截链、参数解析和转换器准备调用。¦返回值处理器选择写正文或视图，异常解析器处理相应失败。', '@RestController\nclass EmployeeController {\n  @GetMapping("/employees/{id}")\n  EmployeeVO get(@PathVariable long id) { return service.get(id); }\n}', 'java', 'Servlet应用需要HTTP接口时采用MVC；事件流和非阻塞链需另评估WebFlux等，不混用解释。', '一个请求可在映射、参数、handler、序列化多个位置失败；并非全都进Service。', '为每边界构造失败输入，并通过断点/日志确认执行到哪一步。', MVC);
put('spring-6', 'HttpMessageConverter按类型和媒体类型读写HTTP内容；Jackson是常见JSON转换库。@RequestBody与@ResponseBody引导转换过程，序列化方向必须清楚。', '读取Content-Type并选择能读目标Java类型的转换器。¦JSON→DTO是反序列化，随后校验输入约束。¦Java返回值→JSON是序列化，按Accept等条件选择表示。', 'record EmployeeDTO(String username) {}\nrecord EmployeeVO(long id, String username) {}\n// HTTP body {"username":"xiaozhi"} → DTO\n// new EmployeeVO(108,"xiaozhi") → JSON响应', 'java', 'JSON API使用现有转换基础设施；文本、文件或流响应可以选其他转换器，不必全部包装JSON。', 'Jackson不会自动做业务唯一性和授权。序列化发生在事务提交后时，其失败不能回滚已提交数据。', '测试错误媒体类型、非法JSON、未知/敏感字段；确认输出无passwordHash且时间格式稳定。', 'https://docs.spring.io/spring-framework/reference/web/webmvc/message-converters.html');
put('spring-7', 'MVC异常解析将失败转换为响应；Interceptor围绕已映射handler执行；CORS约束浏览器跨源读取。这三种横切机制的位置与目标不同。', 'HandlerMapping之后调用preHandle，放行才继续调用handler。¦handler或解析失败可由MVC异常解析设施处理。¦CORS预检与实际请求按配置响应，认证授权仍独立执行。', '@RestControllerAdvice\nclass ApiErrors {\n  @ExceptionHandler(DuplicateKeyException.class)\n  ResponseEntity<Map<String,String>> duplicate() {\n    return ResponseEntity.status(409).body(Map.of("message","用户名已存在"));\n  }\n}', 'java', '统一MVC错误与handler日志可用这些扩展；完整认证宜放安全过滤链，不靠Interceptor替代全部安全体系。', 'Filter前置异常不自动进入Advice；async dispatch使拦截与清理更复杂，必须确认线程上下文。', 'Filter、preHandle、Controller和afterCompletion逐处注入失败，检查响应与清理。', 'https://docs.spring.io/spring-framework/reference/web/webmvc/mvc-servlet/handlermapping-interceptor.html');
put('spring-8', 'Starter提供一组常见依赖，自动配置在条件满足时提供Bean与设置。Boot减少手动组装，不改变HTTP→业务→数据库主链职责。', 'classpath上的库和属性决定候选自动配置。¦条件检查用户是否已提供相应Bean等。¦创建服务器、MVC等基础设施，用户配置可覆盖或使部分默认退让。', '@SpringBootApplication\npublic class Application {\n  public static void main(String[] args) {\n    SpringApplication.run(Application.class,args);\n  }\n}\n// 调试自动配置原因：启动时使用--debug查看条件报告', 'java', '常规Spring应用用Boot简化工程化；理解自动配置条件比复制大量手动配置更有效。', 'Boot不同主版本、Starter与Web栈会改变条件，不应把某版默认当永久规则。引入依赖不保证所有功能无配置可用。', '查看条件报告，增加自定义Bean前后比较被采用的配置及实际运行组件。', 'https://docs.spring.io/spring-boot/reference/features/developing-auto-configuration.html');
put('spring-9', '外部配置让部署参数与代码分离；Profile按名称启用配置或组件；最终值由配置来源及优先级决定。Profile不是数据库权限防火墙。', '启动取得文件、环境和参数等属性源。¦选择活跃Profile，创建条件匹配的Bean。¦绑定类型并验证必需配置，展示非敏感生效版本便于排错。', '@ConfigurationProperties("app.invite")\nrecord InviteProperties(Duration timeout) {}\n// application.yml: app.invite.timeout: 2s\n// 注册与校验按项目配置完成', 'java', '环境差异用外部参数，行为替换用明确Profile/条件；不要为每参数建立复杂Profile组合。', '动态配置刷新不等于所有Bean立即重建。密码不能仅靠放进prod文件实现保护。', '同一制品在两套环境运行，验证数据库地址和timeout最终值，不输出秘密。', 'https://docs.spring.io/spring-boot/reference/features/external-config.html');
put('spring-10', 'Actuator提供管理端点与指标集成，Advice处理Web异常，全局MVC配置修改转换/跨域等基础行为。运行可观测、错误契约与全局设置是三条责任线。', '按需求暴露健康与指标端点，并控制管理权限。¦健康探针按存活/就绪意义配置，依赖失败的影响要明确。¦统一错误保留正确HTTP状态，配置修改需回归全部接口。', 'management:\n  endpoints:\n    web:\n      exposure:\n        include: health,info\n# 暴露指标等端点前另配置认证、网络与敏感信息策略', 'yaml', '部署管理与监控需要Actuator；简单实验可只开必要端点，不应默认公开全部。', 'health=UP不证明每个业务正常；错误全包200会破坏客户端和监控语义。', '检查管理端点匿名访问范围，模拟依赖故障观察就绪行为；回归错误响应状态。', 'https://docs.spring.io/spring-boot/reference/actuator/endpoints.html');

put('orm-1', 'JDBC定义Java数据库访问API；Connection承载会话与事务，PreparedStatement承载SQL与参数，ResultSet逐行承载查询数据。驱动完成数据库协议通信。', '从DataSource取得连接并准备SQL。¦以setX绑定参数，执行后读取结果或更新行数。¦关闭ResultSet和Statement，并归还连接；框架事务内由框架管理绑定连接。', 'try (Connection c = dataSource.getConnection();\n     PreparedStatement p = c.prepareStatement("SELECT username FROM employee WHERE id=?")) {\n  p.setLong(1,108L);\n  try (ResultSet r = p.executeQuery()) {\n    if (r.next()) System.out.println(r.getString("username"));\n  }\n}', 'java', '理解JDBC用于解释MyBatis底层；业务框架已经管理资源时不要随意独立取连接破坏事务。', '示例是独立JDBC场景。驱动服务端预编译策略受配置影响，PreparedStatement接口不等于每次一定同一协议细节。', '检查连接池使用量执行后恢复；事务测试验证所有SQL是否使用正确的事务连接。', JAVA);
put('orm-2', 'DataSource是获取连接的接口；连接池复用物理连接并限制同时借出的数量；HikariCP是连接池实现。限制也是数据库负载保护，不能只看池是否够大。', '请求借连接，有空闲即用，否则按超时等待。¦SQL和事务期间连接被占用；逻辑close通常归还池。¦监测活跃、空闲、等待与获得超时，区分池不足和SQL过慢。', 'spring:\n  datasource:\n    hikari:\n      maximum-pool-size: 8\n      connection-timeout: 2000\n# 示例值用于实验，不能直接当生产最佳配置', 'yaml', '按数据库承载、SQL时间、实例总数压测调池；先解决慢SQL与泄漏，再考虑增大。', '8条连接不是8个用户上限。多实例每池8会叠加数据库总连接，更多连接可能增加锁与IO竞争。', '延长SQL时间观察active与pending，归还后应下降；按单实例及全部实例测吞吐和p99。', 'https://github.com/brettwooldridge/HikariCP/wiki/About-Pool-Sizing');
put('orm-3', '参数化SQL把输入当数据绑定，避免它变成SQL语法。MyBatis的#{}建立参数，${}直接替换文本；表名和排序列等结构需白名单。', '固定SQL结构并为值保留占位符。¦框架从参数对象读值，交由JDBC按类型绑定。¦不能绑定的结构片段只允许已定义常量，不拼用户原文。', '@Select("SELECT id,username FROM employee WHERE username=#{username}")\nEmployee find(String username);\n// username="x\' OR 1=1 --"仍是一个待匹配的值\n// ORDER BY列名必须从受控枚举映射，不能直接${userInput}', 'java', '所有不可信值采用参数化；数据库账号也需最小权限，形成纵深控制。', '参数化不处理业务越权，不保证任意动态SQL结构安全；客户端过滤不是后端防注入的替代。', '输入引号和典型注入字符串，查询应仅匹配字面值；审查所有${}来源。', MYBATIS);
put('orm-4', 'Mapper是持久化接口，MyBatis代理把方法调用关联到映射语句。Service拿到的是可执行代理而不是手写MapperImpl；代理仍通过SQL/JDBC访问数据库。', '启动扫描注册Mapper代理与映射。¦方法名和namespace定位MappedStatement，参数生成SQL与绑定。¦执行结果按声明类型映射回调用者。', '@Mapper\ninterface EmployeeMapper {\n  @Select("SELECT id,username FROM employee WHERE id=#{id}")\n  Employee find(@Param("id") long id);\n}', 'java', '显式SQL需求适合Mapper方式；不要误把代理机制理解成接口自行包含数据库行为。', 'MyBatis Mapper与MapStruct Mapper是不同注解体系。扫描、namespace和参数名不匹配会导致运行失败。', '检查代理运行时类型，测试已存在与不存在id，并查看实际执行SQL和绑定参数。', MYBATIS);
put('orm-5', '注解和XML是声明映射SQL的两种方式；XML的namespace对应Mapper接口，id对应方法。声明形式不改变JDBC和事务边界。', '接口声明方法与参数。¦注解直接携带SQL，或XML以namespace+id建立映射。¦框架执行时查映射，复杂条件由动态SQL元素生成。', '<mapper namespace="com.example.EmployeeMapper">\n  <select id="find" resultType="com.example.Employee">\n    SELECT id,username FROM employee WHERE id=#{id}\n  </select>\n</mapper>', 'xml', '简单固定SQL可用注解，复杂可读查询可用XML；保持一处明确映射而非重复声明冲突。', 'XML位置与mapper-locations、类型别名或全限定名需配置一致；重名id与接口变更会破坏绑定。', '改变方法名或namespace模拟绑定错误，恢复后验证真实SQL；测试启动资源扫描。', MYBATIS);
put('orm-6', '动态SQL根据条件和集合生成最终SQL，参数映射仍把值绑定为参数。if、where、foreach等决定语句结构，并不自动保证过滤条件足够安全。', '先定义空值、空字符串与空列表的业务语义。¦动态标签按参数生成条件，where处理前导AND等。¦执行前确认UPDATE/DELETE有必要约束，防止条件消失变全表操作。', '<select id="list" resultType="Employee">\n  SELECT id,username FROM employee\n  <where>\n    <if test="name != null and name != \'\'">\n      AND username LIKE CONCAT(\'%\',#{name},\'%\')\n    </if>\n  </where>\n</select>', 'xml', '可选过滤查询适合动态SQL；业务强制条件如tenantId不能做成可随意省略的if。', 'LIKE参数化不消除通配符语义；%和_需按产品要求处理。空IN列表必须明确行为。', '列出每种参数组合生成的SQL和结果，尤其全空、空集合与租户缺失。', 'https://mybatis.org/mybatis-3/dynamic-sql.html');
put('orm-7', 'resultMap显式定义列到属性映射；驼峰设置帮助自动映射查询结果；插件拦截规定执行点，如分页。它们不自动改写INSERT中的数据库列名。', '数据库ResultSet提供列名和值。¦resultMap或自动映射确定目标属性和类型。¦插件可改执行过程，必须检查顺序和版本兼容。', '<resultMap id="employeeMap" type="Employee">\n  <id column="id" property="id"/>\n  <result column="id_number" property="idNumber"/>\n</resultMap>\n<!-- INSERT仍需明确写id_number列 -->', 'xml', '复杂映射和嵌套结果用显式resultMap；简单一致命名可采用自动驼峰映射减少重复。', 'map-underscore-to-camel-case主要用于结果自动映射，不把任意SQL中的idNumber换为id_number。插件可增加COUNT和SQL次数。', '查询id_number验证实体值；记录插件前后SQL、COUNT次数和返回总数。', 'https://mybatis.org/mybatis-3/configuration.html');
put('orm-8', 'PageHelper通过MyBatis插件参与查询分页，常用方式先设置分页上下文再执行目标查询。分页不是新业务层，COUNT与深OFFSET仍有成本。', '校验page和pageSize并限定最大值。¦设置分页后紧邻目标Mapper查询，避免被别的查询消耗。¦取得列表与总数，确认异常路径上下文清理和版本行为。', 'PageHelper.startPage(page, Math.min(pageSize,100));\nList<Employee> rows = mapper.list(filter);\nPageInfo<Employee> info = new PageInfo<>(rows);\n// Mapper查询需紧跟分页设置', 'java', '页码列表适合插件；无限滚动和大数据深分页可评估游标分页，可能不需要总数。', '具体API与上下文清理按使用版本验证。分页排序必须稳定；联表重复行会影响总数语义。', '检查最终LIMIT和COUNT，测试并发与异常后下一请求不继承错误分页设置。', 'https://github.com/pagehelper/Mybatis-PageHelper');
put('orm-9', 'MyBatis-Plus在MyBatis上提供常见CRUD、Wrapper和插件；逻辑删除用条件隐藏记录，自动填充提供审计字段。业务规则和复杂SQL仍由开发者负责。', '声明实体映射和BaseMapper。¦Wrapper明确生成查询或更新条件。¦分页、逻辑删除、填充等配置参与SQL，需观察实际语句。', 'LambdaUpdateWrapper<Employee> w = Wrappers.lambdaUpdate();\nw.eq(Employee::getId,108L)\n .eq(Employee::getVersion,oldVersion)\n .set(Employee::getStatus,0);\nint changed = mapper.update(null,w);', 'java', '重复CRUD多时可减少样板代码；复杂访问仍选择显式Mapper SQL，不必硬套Wrapper。', '示例版本条件不自动增加版本字段，完整乐观锁需配置或显式更新。逻辑删除不删除磁盘记录，唯一键设计需兼容。', '打印SQL检查WHERE、删除过滤和版本更新；空条件更新应被业务拒绝或保护。', 'https://baomidou.com/en/guides/wrapper/');
put('orm-10', 'JPA是持久化规范，Hibernate是常见实现。持久化上下文管理实体状态，脏检查和flush使变更转为SQL；它与MyBatis显式SQL的控制方式不同。', 'EntityManager加载实体并纳入上下文。¦修改受管理实体字段，框架跟踪变化。¦flush阶段发SQL，事务提交完成数据库边界；懒加载可能再发查询。', '@Transactional\npublic void disable(long id) {\n  Employee e = entityManager.find(Employee.class,id);\n  if (e == null) throw new NotFoundException();\n  e.setStatus(0); // 受管理对象，flush时可能产生UPDATE\n}', 'java', '对象关联与状态管理适合JPA风格；精细SQL控制可用MyBatis，选择依据团队与访问模式。', '修改脱管对象不自动写库。懒加载、N+1、flush与批处理时机需要理解，切换框架不是仅替换注解。', '启用SQL统计检查查询数与flush时机；测试事务外关联访问和列表N+1。', 'https://docs.jboss.org/hibernate/orm/current/userguide/html_single/Hibernate_User_Guide.html');
put('orm-11', 'Flyway与Liquibase把Schema变更版本化并记录执行状态，让环境升级可追踪。迁移文件不是天然安全回滚脚本，尤其涉及数据删除和大表。', '为每次结构变化提交迁移与兼容设计。¦部署检查已执行历史并应用新变更。¦滚动发布采用先扩展、兼容写读、再收缩，保留数据恢复途径。', '-- 示例迁移V2__employee_display_name.sql\nALTER TABLE employee ADD COLUMN display_name VARCHAR(100) NULL;\n-- 先部署能兼容NULL的新代码，后续回填，再评估约束', 'sql', '多环境和持续发布应采用迁移管理；手动改生产结构容易与代码漂移。', 'DDL隐式提交、表锁和重建成本按数据库版本检查；修改已执行迁移会破坏校验和历史可信性。', '从旧Schema升级测试，保留旧应用同时访问，测迁移耗时和锁，并演练恢复。', 'https://documentation.red-gate.com/fd/migrations-184127470.html');
put('orm-12', 'DTO表达传输契约，Entity表达业务持久化数据，此处VO指View Object展示表示，Result包装响应。Value Object也常缩写VO，必须先限定语境。', '输入DTO只接允许客户端决定的字段。¦Service校验并构造Entity，补状态、操作者等可信数据。¦输出VO过滤秘密，Result可包装VO，但HTTP状态保持正确。', 'record EmployeeCreateDTO(String username,String name) {}\nrecord EmployeeVO(long id,String username,String name) {}\nrecord Result<T>(String code,T data) {}\n// Entity可含passwordHash；输出VO没有该字段', 'java', '输入、存储和展示形状差异明显时拆对象；简单内部查询不必机械复制完全相同的三份类。', 'DTO不限入站，VO不是所有项目固定含义。对象分开也不能代替权限和显式安全映射。', '序列化响应断言没有敏感字段；输入额外权限或id时确认不能越权覆盖。');

put('enterprise-1', 'Controller负责HTTP契约，Service负责完整业务用例，Mapper负责数据库访问。分层让协议变化不拖着业务规则一起改变，也让非HTTP入口可复用业务。', 'Controller取得DTO和可信操作者。¦Service判断权限、不变量和事务边界，构造数据。¦Mapper执行SQL并返回结果，Service决定业务结果，Controller映射HTTP。', 'Controller: create(dto) → service.create(dto,operator)\nService: requirePermission → buildEmployee → mapper.insert\nMapper: INSERT employee(...) VALUES(...)\nReturn: id → EmployeeVO → HTTP201', 'plaintext', '需要复用、测试和维护边界时分层；小功能不必每层再造多个只转发的接口。', '规则写在Controller会让导入或MQ绕过它；Mapper不应偷偷负责请求权限。', '从HTTP和批量导入两入口调用同一Service，验证权限、唯一性与事务结果一致。');
put('enterprise-2', '输入校验检查格式边界，业务校验检查允许性，数据库约束兜住并发不变量；统一错误契约将这些失败清晰反馈，不能全部伪装成成功。', 'Bean Validation拒绝空或范围非法输入。¦Service验证状态与资源权限。¦数据库唯一冲突映射409，意外失败映射适当5xx并关联traceId。', 'record CreateDTO(@NotBlank String username) {}\n@PostMapping\nResponseEntity<EmployeeVO> create(@Valid @RequestBody CreateDTO dto) {\n  return ResponseEntity.status(201).body(service.create(dto));\n}', 'java', '多接口应统一错误Schema和语义；输入格式与业务规则分开更利于定位和测试。', '@Valid不证明用户名唯一；错误必须避免泄露SQL、token或敏感内部信息。', '空值400、重复409、无权限403、内部故障5xx分别测试，并确认数据库不产生非法记录。', 'https://docs.spring.io/spring-framework/reference/web/webmvc/mvc-controller/ann-methods/requestbody.html');
put('enterprise-3', '认证确认身份，授权确认身份可以对资源做什么；RBAC将权限分给角色；JWT承载声明，可签名验证但载荷通常并未加密。', '验证token签名、时间及配置要求的issuer/audience。¦取得可信subject/角色，禁止直接信任前端operatorId。¦按动作与具体资源授权，包括租户与数据归属。', '// 业务授权伪代码\nIdentity who = verifiedIdentity();\nEmployee target = repository.get(id);\npermissions.require(who,"employee:edit",target.tenantId());\nservice.edit(target,validatedDto);', 'java', 'RBAC适合角色权限管理，资源归属还需对象级规则；token或Session选择依据整体安全方案。', 'JWT解码不是验证。管理员角色也可能只能管理本租户；签名正确不说明凭据未被撤销。', '修改token载荷、过期token、其他租户id与缺角色分别验证拒绝，不能只测正常登录。', 'https://docs.spring.io/spring-security/reference/servlet/authorization/index.html');
put('enterprise-4', 'Spring Security以过滤链统筹身份与权限；PasswordEncoder对密码进行单向编码并验证。生产密码不应明文、固定弱密码或快速MD5保存。', '首次设置密码调用encode生成含盐与成本信息的编码。¦登录调用matches比对原始输入，不做可逆解密。¦认证后使用会话或短期凭据，避免每请求重复执行昂贵密码验证。', 'PasswordEncoder encoder = PasswordEncoderFactories.createDelegatingPasswordEncoder();\nString stored = encoder.encode("user-selected-secret");\nboolean ok = encoder.matches("user-selected-secret",stored);\n// 保存stored；不要打印原密码', 'java', '生产登录使用成熟安全体系和经压测的编码成本；课程MD5例不能直接迁移。', '示例工厂策略依版本，应检查生成前缀与算法。哈希不是加密，也不能防弱密码字典猜测或凭据泄露。', '同密码多次编码通常结果不同，matches均成功；错误输入失败，并测登录CPU、限速与升级路径。', 'https://docs.spring.io/spring-security/reference/features/authentication/password-storage.html');
put('enterprise-5', 'OSS与MinIO提供对象存储，文件按bucket/key与元数据访问。应用负责上传身份、访问授权、业务记录与清理，URL不天然等于公开权限。', '验证上传请求，生成不可猜且不冲突的对象key。¦文件存对象存储，数据库保存key和归属而非通常直接存大二进制。¦下载时再次授权，签发限时URL或代理流。', 'employee表：avatar_key = "tenant-7/avatar/108/<random>"\n存储：私有bucket + 此key + image bytes\n下载：验证operator可查看员工108 → 签发短期GET URL', 'plaintext', '大文件和多实例共享文件适合对象存储；本地临时文件只用于可丢弃处理，不作为唯一持久副本。', '预签名URL在有效期内可被持有者使用，需限制期限；数据库回滚不自动删除已上传对象。', '未授权访问应拒绝，URL过期后失效；模拟上传成功但DB失败，验证孤儿清理。');
put('enterprise-6', '缓存保存可重复计算或读取的结果；Spring Task按时间触发方法。缓存改变读路径，定时任务增加后台入口，两者都需与多实例和失败模型结合。', '读取缓存命中即返回，未命中按受控回源取得并设置TTL。¦写数据后按策略失效，接受或限制并发旧值窗口。¦定时任务在每个实例都可能触发，必要时用任务协调与幂等。', '@Scheduled(cron="0 0 2 * * *", zone="Asia/Shanghai")\npublic void archive() {\n  archiveBatchForDate(clock.instant());\n}\n// 需启用调度；批次标识唯一，重复调用安全', 'java', '频繁且可容忍一定旧值的读取用缓存；时间触发后台处理可用Task，小项目不必马上用独立调度集群。', 'TTL不等于精准业务失效；本地@Scheduled不能保证整个集群只执行一次。', '重启两实例观察任务触发，断言批次不会重复处理；缓存失效同时验证数据库压力与新值可见性。', 'https://docs.spring.io/spring-framework/reference/integration/scheduling.html');
put('enterprise-7', 'WebSocket在单连接上双向传消息；SSE通过HTTP持续服务器到客户端文本事件。两者解决实时推送，不能代替业务最终状态查询。', '认证后建立长连接并关联用户或任务。¦服务端发送带id的状态事件，客户端更新界面。¦断连时重连并按任务API补查，避免丢消息导致永久错误显示。', 'const stream = new EventSource("/exports/42/events");\nstream.addEventListener("completed", e => {\n  const result = JSON.parse(e.data);\n  showDownload(result.url);\n});', 'javascript', '单向进度通知用SSE较简单；需要高频双向会话可用WebSocket，普通低频状态也可轮询。', 'EventSource原生Header控制有限；跨域凭据需设计。消息收到并不自动证明消息对应的事务已提交。', '任务完成前断网再重连，页面应通过补查获得最终结果；测试连接与权限过期。', 'https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events');
put('enterprise-8', '邮件短信是具有外部副作用的远程服务，HttpClient发网络请求。超时、拒绝和成功后响应丢失都可能发生；本地数据库无法替外部服务回滚。', '为连接、读取与整体操作设置预算。¦重要通知用可恢复任务记录或Outbox，而非长事务等待远端。¦失败分类后限次重试，发送业务标识实现可用的去重。', 'HttpClient client = HttpClient.newBuilder()\n  .connectTimeout(Duration.ofSeconds(2)).build();\nHttpRequest req = HttpRequest.newBuilder(URI.create(url))\n  .timeout(Duration.ofSeconds(3)).GET().build();\nHttpResponse<String> r = client.send(req,HttpResponse.BodyHandlers.ofString());', 'java', '远端能力必需时调用，非核心通知可异步；只读GET示例也需按状态处理结果。', '超时不保证供应商未执行。JDK客户端不同超时层含义需明确；敏感凭据不能放日志。', '模拟连接拒绝、响应慢、500及成功响应丢失，检查线程、连接与重试数量。', 'https://docs.oracle.com/en/java/javase/21/docs/api/java.net.http/java/net/http/HttpClient.html');
put('enterprise-9', 'POI解析和生成Office文件；导入把行变成业务命令，导出把查询变成文件。容量、格式、授权与部分失败是核心边界，不只是循环读写单元格。', '导入逐行校验并报告行号，定义全回滚或部分成功。¦大导出分页/游标查询，使用受控内存写入方案。¦异步任务记录状态，将生成文件保存私有存储并授权下载。', 'try (SXSSFWorkbook workbook = new SXSSFWorkbook(100)) {\n  Sheet sheet = workbook.createSheet("employees");\n  sheet.createRow(0).createCell(0).setCellValue("username");\n  // 分批查询、逐行写入；OutputStream由调用方正确关闭\n  workbook.write(output);\n  workbook.dispose(); // 清理临时文件\n}', 'java', '大数据导出需要流式与任务化，小表可同步；并发批量任务设限额避免挤占在线资源。', '示例需POI依赖；SXSSF仍有临时文件和某些对象内存。公式、日期类型、单元格格式与恶意大文件需处理。', '用目标规模测堆、磁盘、耗时；故意在第100行失败，核对行报告与规定事务结果。', 'https://poi.apache.org/components/spreadsheet/how-to.html');
put('enterprise-10', '幂等让同一业务命令重复执行得到既定结果，防重复按钮只改善体验；乐观锁检测版本冲突，悲观锁提前锁资源。业务边界决定要共同保证哪些操作。', '定义幂等key作用域与请求内容一致规则。¦key唯一记录和业务结果在可靠边界内写入，重复返回已有结果。¦并发修改可用version条件更新，或事务内锁定读，失败显式反馈。', 'UPDATE employee SET name=?,version=version+1\nWHERE id=? AND version=?;\n-- rows=0可能是不存在或版本冲突，按业务契约区分\n-- 幂等请求另有UNIQUE(tenant_id,request_key)记录', 'sql', '网络重试、支付和创建命令需要幂等；低冲突编辑可用乐观锁，高冲突复杂规则再考虑锁定。', '相同key不同内容不应悄悄当相同请求。分布式锁不保证结果持久，也不自动处理锁超时后的旧执行者。', '并发重复key、成功后超时重试、两个编辑版本分别测试，断言唯一效果与可解释返回。');
put('enterprise-11', '审计回答谁何时对哪个资源做何操作；日志帮助诊断，规范与维护性降低理解变更成本。审计身份必须来自可信认证，不来自任意Body字段。', 'Service取得可信operator与资源标识。¦核心状态变化和必要审计在明确事务/事件边界记录。¦访问审计受限，敏感字段脱敏或最小保存。', 'INSERT INTO employee_audit(employee_id,operator_id,action,created_at)\nVALUES(108,42,"CREATE",CURRENT_TIMESTAMP);\n-- operator_id来自认证上下文，不由前端自由决定', 'sql', '敏感操作需可追溯审计；调试细节不必全入永久审计表。', '异步审计可能落后或失败，可靠性目标要明确。ThreadLocal在请求结束和异常路径必须清理。', '伪造Body操作者应无效；并发请求审计身份不能串号，回滚后审计按设计保持一致。');
put('enterprise-12', '配置中心集中管理和分发配置版本，客户端取得本地快照。发布成功、客户端收到、组件真正采用是三个不同节点。', '发布带版本的配置并限制权限。¦客户端读取或订阅更新，校验后采用。¦需要刷新组件时执行明确流程，记录生效版本与失败并可回退。', '配置v12：notify.timeout=2s\n实例A：收到v12 → 校验通过 → client重建 → activeVersion=v12\n实例B：仍v11 → 指标展示差异 → 排查订阅或刷新失败', 'plaintext', '多实例需要统一配置与审计时采用；简单单应用可先用部署注入，不必新增控制面。', '中心不可用应明确使用旧快照还是拒绝启动。刷新值不等于已创建的HTTP客户端自动换超时。', '修改配置后查询各实例非敏感版本，模拟中心故障和非法值，验证回退策略。');
put('enterprise-13', 'ECharts将数据映射为前端图形，后端统计API提供授权后的聚合结果。图表属于展示支线，不执行SQL或保证统计口径正确。', '数据库按口径和时间窗口聚合。¦VO明确label、value、单位与缺失值。¦前端映射坐标、系列与交互，标注时间和统计范围。', 'chart.setOption({\n  xAxis:{type:"category",data:["研发","运营"]},\n  yAxis:{type:"value",name:"员工数"},\n  series:[{type:"bar",data:[12,7]}]\n});', 'javascript', '趋势、分布和比较适合图表；只有单事实或极小列表时文本表格更直接。', '图表不能修复错误JOIN重复计数；纵轴截断、不同单位与缺失值填0可能误导。', '拿小数据手算聚合并核对图形数值；检查权限过滤、时区与时间窗口。', 'https://echarts.apache.org/handbook/en/get-started/');

put('middleware-1', 'Redis常见基础结构包括String、Hash、List、Set、Sorted Set：分别处理标量、字段、序列、去重和按分数排序。它们只是常见五类，不是Redis全部类型。', '按所需原子命令与查询方式选结构。¦设计key范围、TTL和大小，避免无限增长与大key阻塞。¦多个命令组合需评估原子边界，单命令原子不代表整业务事务。', 'SET employee:108:name "小智" EX 60\nHSET employee:108 username xiaozhi status 1\nSADD department:7:employees 108\nZADD active-ranking 10 108\nLRANGE recent-events 0 9', 'plaintext', '按key查询和计数排序适合Redis；复杂关系JOIN或权威事务通常仍交关系库。', 'List并不自动形成可靠任务队列；Redis Cluster多key操作需考虑同槽。大key和高频热点需监测。', '查询类型、TTL和内存；并发执行目标命令检查语义，再测试组合步骤中断后的状态。', 'https://redis.io/docs/latest/develop/data-types/');
put('middleware-2', '穿透是不存在数据持续回源，击穿是热点失效并发回源，雪崩是大范围失效或缓存故障导致回源潮。RDB/AOF帮助恢复Redis，不解决主库缓存一致性。', '不存在结果可短时缓存，入口先验证无效参数。¦热点失效用受控重建、逻辑过期等策略限制回源。¦分散TTL、限流隔离和数据库保护处理整体失效；按恢复目标配置持久化。', '缓存key不存在 → 校验id\n数据库也不存在 → 缓存空结果短TTL\n热点失效 → 一个重建者，其余等待或用允许的旧值\n全局Redis失败 → 有限回源，超限明确拒绝/降级', 'plaintext', '先识别故障类型再选机制；低访问小表不必引入布隆过滤器和复杂重建链。', '布隆过滤器有误报，空缓存也占空间。TTL随机化不能应对Redis全挂；无限回源会拖垮数据库。', '压测不存在id、同一热点过期和缓存不可用三组场景，观测数据库QPS、错误率与积压。', 'https://redis.io/docs/latest/operate/oss_and_stack/management/persistence/');
put('middleware-3', 'Redis复制提供副本，Sentinel监测并协调主节点切换，Cluster分配哈希槽，Redisson是Java客户端及高级能力封装。它们不能混为“用了Redis就高可用”。', '客户端按部署模式连接并路由key。¦复制传播数据，故障切换可能有未传播写入风险。¦Cluster多key操作需要同槽或重新设计；Redisson锁等能力还需正确配置和使用。', 'Cluster：key → hash slot → 负责节点\nSentinel：监测主节点 → 协调切换 → 客户端重连\nRedisson：Java调用 → 客户端协议 → Redis节点', 'plaintext', '需要数据冗余、切换或容量分片时选择相应模式；单机开发环境不代表生产故障模型。', '异步复制与切换不能自动保证零数据丢失。客户端库无法把任何业务锁都变成强一致安全。', '演练节点下线与网络分区，检查客户端恢复、写可见性、错误率和失效锁影响。', 'https://redis.io/docs/latest/operate/oss_and_stack/management/scaling/');
put('middleware-4', '分布式锁让多进程协调同一临界资源，锁拥有者、租约与失效必须明确。锁只是许可，最终资源仍可能需要版本或fencing拒绝过期执行者。', '原子取得锁，写入随机拥有者标识及租约。¦业务执行期间评估超时和续期，不能无限假定仍持有。¦释放时原子检查拥有者再删除；资源侧可用递增令牌拒绝旧写。', 'SET lock:archive:2026-10-13 <unique-owner> NX PX 30000\n-- 释放须比较value仍等于unique-owner再DEL，通常用原子脚本\n-- 不能直接DEL，因为锁可能已过期并归别人', 'plaintext', '跨实例任务互斥可用锁；资金库存等核心不变量应优先由权威数据库约束保证。', '暂停超过租约后旧执行者继续运行，新持有者也可能在执行。自动续期不是所有故障下永久互斥证明。', '暂停持有者超过租约，再启动另实例，检查资源版本/fencing能否阻止迟到更新。', 'https://redis.io/docs/latest/develop/clients/patterns/distributed-locks/');
put('middleware-5', 'RabbitMQ以交换器和队列路由为核心，Kafka以分区追加日志及offset消费为核心，RocketMQ有自己的主题队列与消息能力。异步通信是共同点，存储、确认与重放不同。', '业务提交产生事件，生产者发送到产品对应目的地。¦Broker保存与路由，消费者按队列或分区处理。¦消费提交或确认与生产确认分开，失败导致重投或重读。', 'RabbitMQ：producer → exchange → queue → consumer ack\nKafka：producer → topic partition → consumer offset\nRocketMQ：producer → topic/queue → consumer result\n业务事件：EmployeeCreated(eventId, employeeId)', 'plaintext', '按路由、顺序、重放、吞吐与运维需要选产品；小规模无需同时部署三种。', 'Kafka顺序主要是单分区，不是整个系统全局顺序。Broker确认不是消费者业务完成。', '在生产成功后、消费提交前分别崩溃，记录重复、丢失和重放行为，验证业务去重。', 'https://www.rabbitmq.com/docs/confirms');
put('middleware-6', '发布确认回答Broker是否接收，消费确认回答消费者是否完成；重试处理可恢复失败，死信隔离永久失败。可靠性要从业务提交到最终处理端到端定义。', '业务与Outbox共同提交，发布器失败可再次发送。¦消费者在同事务中去重并修改业务，提交后ack。¦失败按分类限次退避，永久错误转死信并告警与恢复。', 'BEGIN;\nINSERT INTO processed_event(event_id) VALUES(?); -- 唯一键去重\nUPDATE search_sync_job SET status="done" WHERE event_id=?;\nCOMMIT;\n-- 成功提交后ack；重复event_id按既有结果安全处理', 'sql', '关键事件需要可靠投递、幂等消费与积压监控；无关紧要遥测可采用不同保证。', '消费者提交后ack前崩溃会重复；ack先于提交可能丢业务。自动无限重试永久错误会阻塞队列。', '在提交前、提交后ack前和ack后注入崩溃，断言业务只产生一份效果且死信可恢复。', 'https://www.rabbitmq.com/docs/confirms');
put('middleware-7', 'Elasticsearch用倒排索引支持全文检索和聚合，mapping/analyzer影响分词与匹配；关系数据库提交和搜索可见时间是不同边界。', '业务数据按mapping生成搜索文档。¦索引更新通过refresh等机制变得可搜索，不同于写请求立即强一致读取。¦查询评分与过滤返回命中，授权字段必须按可信条件过滤。', 'GET /employees/_search\n{ "query": { "bool": {\n  "must": [{"match":{"name":"小智"}}],\n  "filter": [{"term":{"tenant_id":7}}]\n}} }', 'plaintext', '全文检索、相关性排序与搜索聚合需要时使用；精确ID点查不必全部走搜索引擎。', 'match与term语义不同。派生索引可能旧，不能仅靠旧索引决定敏感权限。', '检查mapping与分析词元，测试写后搜索延迟、租户过滤、索引重建和同步积压。', 'https://www.elastic.co/docs/solutions/search');
put('middleware-8', 'Nginx反向代理代表服务器接受连接并转发，可终止TLS、提供静态文件和负载分配。代理有自己的超时、缓冲和路径变换边界。', '按listen/server_name/location选择处理规则。¦proxy_pass按是否携带URI等规则构造上游路径。¦取得上游响应后返回客户端，超时和502可发生在代理而非Controller。', 'location /api/ {\n  proxy_pass http://employee_app/;\n}\n# 此URI配置把/api/employees转为上游/employees\n# 需要保留/api时按官方规则另配置并测试', 'nginx', '公网入口、TLS和多实例路由可用代理；本地单应用调试可直接连接，避免多层路径混淆。', '末尾斜杠和location规则影响URI。真实客户端IP应仅信任可信代理，不能直接信任任意转发头。', '在上游记录实际URI，测试/api/路径、超时与下线节点；区分代理status与upstream_status。', 'https://nginx.org/en/docs/http/ngx_http_proxy_module.html');
put('middleware-9', 'MinIO/OSS保存对象，任务框架决定谁何时执行任务。报表生成把二者串联：调度和执行可靠性不能由对象存储替代。', '提交任务记录，返回jobId而非假称文件已生成。¦工作节点领取并分页生成，上传对象后写最终状态。¦客户端查询状态并授权下载，失败任务按规则可重试和清理临时文件。', 'job42: PENDING → RUNNING → UPLOADED(key) → SUCCEEDED\n失败：记录error、attempt与nextRetryAt\n重复执行：按jobId避免发布多个最终结果', 'plaintext', '长报表、批处理适合后台任务；很短查询结果无需为了异步而强制任务化。', '上传成功但任务状态写失败会留孤儿；调度器触发不保证执行恰好一次。', '在生成、上传、状态提交各阶段崩溃，确认恢复不会丢结果或无限占资源。');
put('middleware-10', '缓存与搜索通常是权威数据的派生视图，异步处理改变完成时间与失败边界。主流程已成功和所有支线已同步是不同状态。', '先定义权威数据与每支线可接受延迟。¦用持久事件传播变更，消费者可重试并去重。¦观察最老未完成事件、错误与校验差异，安排补偿重建。', '员工提交成功：employee.id=108\n缓存：失效，下一读重建\n搜索：event108待同步\n通知：invite108待发送\n界面：已创建；邀请发送中', 'plaintext', '提高读性能或解耦非核心工作时使用支线；强一致规则不应依赖未同步的派生视图。', '“最终”必须有收敛机制和时限目标，不能当成永久不同步的借口。', '暂停消费者后恢复，记录延迟并验证全部积压收敛；抽样比较主库与派生视图。');

put('microservices-1', '微服务是独立部署的服务边界，模块化单体是在同进程内保持职责边界。拆服务换取独立变化与运维，也引入网络、契约和一致性成本。', '先在单体划定模块和禁止的依赖。¦确认某模块需要独立部署、伸缩或团队负责。¦将边界变HTTP/MQ契约，补超时、版本、观察与数据迁移。', '第一步：员工模块 → 通知接口（同进程）\n第二步：通知实现 → 独立消费者（跨进程）\n保留：员工创建事务在员工数据库\n新增：事件可靠性、重试、去重、运行监控', 'plaintext', '业务与组织确有独立演进需要时拆分；普通规模CRUD可优先模块化单体。', '微服务不自动解决慢SQL和单点数据库；拆分太细可能让一个业务到处远程等待。', '比较拆分前后部署耦合、故障影响、延迟、运营成本，验证原目标而非服务数量。');
put('microservices-2', 'DDD以领域语言和业务不变量建模；限界上下文限定术语含义；服务边界是部署决策，可对应一个或多个模块，不能只按表拆。', '与业务确认员工在身份、薪资等场景的不同含义。¦在上下文内定义聚合和规则，跨边界用明确契约。¦避免共享可随意修改的万能Entity，让数据拥有者清晰。', '身份上下文：EmployeeAccount(id,username,status)\n薪资上下文：PayrollEmployee(id,payGrade,bankRef)\n共享标识：employeeId\n跨边界通知：EmployeeDisabled', 'plaintext', '复杂业务语言和规则适合DDD；简单CRUD也可用清晰模块，不必引入所有DDD术语。', '限界上下文不是数据库Schema同义词。聚合必须有规则与一致性范围，不是任意大对象图。', '列出同名字段的业务含义和拥有者；用跨上下文用例检查是否出现大量循环调用。');
put('microservices-3', 'Spring Cloud提供分布式集成生态，Alibaba生态集成相应组件，Nacos负责服务发现和配置等控制面能力。版本组合和服务注册协议需明确。', '实例注册地址与元数据，并保持存活信息。¦消费者取得发现结果，结合健康与负载策略选实例。¦配置分发到本地客户端，观察实际版本与可用性。', 'employee-service实例A：10.0.0.1:8080\nemployee-service实例B：10.0.0.2:8080\n调用方：名称 → 发现列表 → 负载选择 → HTTP\n配置：namespace/group/dataId → 版本快照', 'plaintext', '动态多实例和统一配置有需求时采用；固定少量地址可先用简单配置或平台Service发现。', '注册存在不代表业务就绪，发现列表有传播延迟；Cloud各版本不能任意拼接。', '下线与未就绪实例实验验证流量排除；确认配置中心故障时客户端与新实例启动行为。', 'https://nacos.io/en/docs/latest/what-is-nacos/');
put('microservices-4', 'OpenFeign把接口声明变成HTTP调用，LoadBalancer从实例集合选择目标。远程调用看似Java方法，但有序列化、连接、失败和重试边界。', '接口注解定义路径、参数和响应类型。¦调用时编码请求并由实例选择器决定地址。¦客户端按超时返回或抛异常，业务按状态分类，控制重试预算。', '@FeignClient(name="employee-service")\ninterface EmployeeClient {\n  @GetMapping("/employees/{id}")\n  EmployeeVO get(@PathVariable("id") long id);\n}', 'java', '已有Cloud HTTP服务可用声明客户端；单次调用也可用普通HTTP客户端，避免不需要的生态依赖。', 'Feign重试默认取决于框架配置与版本。不能把数据库事务跨HTTP自动延长到远端。', '让一个实例慢和一个实例下线，观察选择、超时与调用次数；核对实际编码参数。', 'https://docs.spring.io/spring-cloud-openfeign/reference/');
put('microservices-5', 'Gateway处理入口路由与边缘策略；Sentinel和Resilience4j提供运行保护能力，具体算法与配置不同。熔断、限流和并发隔离应分别设计。', '网关先处理路由和允许的入口策略。¦调用保护测量错误或慢调用，并按规则拒绝或探测恢复。¦后备结果明确业务未完成或简化状态，不能返回伪成功。', '核心创建 → 写员工成功\n通知依赖熔断OPEN → 不同步调用\n响应：created=true, invitation="PENDING"\n恢复：Outbox消费者重试真实发送', 'plaintext', '故障依赖会拖垮主流程时配置保护；局部轻量应用不必同时装两套治理库。', '网关认证不替代资源级授权。TimeLimiter对阻塞操作的取消能力受客户端支持限制。', '注入慢调用与异常，确认OPEN拒绝、HALF_OPEN试探、恢复及线程资源释放。', 'https://resilience4j.readme.io/docs/circuitbreaker');
put('microservices-6', 'Trace关联一次分布式操作，Span记录其子操作，parent关系表示因果，context在HTTP或消息中传播。追踪观察耗时，不自动给根因。', '入口创建或接受合法trace context。¦HTTP、SQL和MQ操作建立子span并传播关联。¦采样导出到后端，按长span结合资源指标定位候选瓶颈。', 'trace T\n  HTTP POST /employees: 180ms\n    validation: 2ms\n    SQL insert: 140ms\n    role grant: 10ms\n// SQL长还需区分锁、IO、连接与网络', 'plaintext', '跨服务与多依赖排错需要追踪；小系统也可先保留requestId和分段耗时。', '跨度时间可能含等待与网络；不同机器时钟、采样与缺失span影响解释。', '用已知慢SQL与慢外部API分别验证trace能定位对应段，再与数据库等待指标交叉核实。', 'https://opentelemetry.io/docs/concepts/signals/traces/');
put('microservices-7', '分布式配置、缓存与锁将共享信息放进外部系统，却各自有传播、过期和失败边界。外部化不等于全实例立即强一致。', '配置用版本与快照说明生效状态。¦缓存标明权威源、TTL及失效策略。¦锁标明拥有者、租约与资源侧保护，故障后有明确恢复。', '实例A：config v12，cache key TTL60s\n实例B：config v11，cache miss\n锁owner=C，leaseUntil=t+30s\n结论：三种状态分别观察，不用一个“Redis正常”代替', 'plaintext', '多实例共享需要才外部化；不同保证必须分别设计，避免过度依赖一个基础设施。', '配置刷新不会自动重建所有组件，缓存旧值与锁过期是不同风险；Redis可用不证明业务正确。', '分别延迟配置、关闭缓存和暂停锁持有者，测试每条状态路径而非统一重启。');
put('microservices-8', '2PC由协调者与资源参与者分阶段提交，TCC由业务提供Try/Confirm/Cancel，Saga用步骤与补偿管理长流程。三者代价与可恢复语义不同。', '先明确业务需要原子提交还是允许补偿收敛。¦TCC预留必须处理空取消、重复与悬挂；Saga每步和补偿均需幂等。¦持久化流程状态，故障后继续或补偿，而不依赖内存执行栈。', 'Saga：创建员工档案 → 开通账号 → 分配设备\n设备失败：撤销账号 → 标记档案待处理/撤销\n补偿状态：PENDING → RETRYING → COMPENSATED\n不能补偿的步骤：转人工并记录原因', 'plaintext', '跨服务长业务按风险选择；可以把强一致数据放同库时，普通本地事务更简单。', '补偿不是时间倒流，邮件已发不可取消。2PC在故障时可能阻塞，具体保证依实现与资源支持。', '每步骤前后崩溃并重启协调流程，验证无永久悬挂、重复补偿和资源泄漏。');
put('microservices-9', 'CAP讨论网络分区时一致性和可用性承诺的冲突；BASE是较弱即时一致性的设计表达；最终一致性要求没有新写且故障恢复后副本收敛。', '先定义业务读取需要最新值还是允许旧值。¦分区时选择拒绝部分操作或返回可能不一致结果，并明确范围。¦恢复后通过复制、事件重放或对账保证收敛，监测时间目标。', '权限变更：不能确认最新授权 → 按风险拒绝敏感操作\n搜索名称：允许短暂旧值 → 展示后续同步状态\n恢复条件：事件补齐、版本一致、积压年龄低于目标', 'plaintext', '不同业务可用不同一致性等级；权限和资金不能只因为方便就允许任意旧值。', 'CAP不是正常网络下随意“三选二”。最终一致性没有修复机制和时间目标就只是愿望。', '模拟分区与传播延迟，分别验证返回策略、恢复后数据一致和最大不一致窗口。');
put('microservices-10', '限流限制到达速度，隔离限制占用资源，熔断暂停不健康依赖，降级选择可接受简化结果。它们互补，但含义与触发条件不同。', '入口按用户/租户/总量设合理配额。¦依赖用独立并发限额和超时预算，避免挤占核心资源。¦熔断后拒绝或降级，恢复探测；重试加退避并受总预算约束。', '报表：最多2个运行，队列20，超限返回明确忙碌\n在线CRUD：独立连接/任务预算\n短信：500ms预算，故障OPEN，异步待发送\n重试：限次数+抖动，禁止无限即时循环', 'plaintext', '有明确过载与故障传播风险时使用；先测资源边界，数值不能凭经验照抄。', '限流不修复慢SQL；降级不能编造正确业务结果。每层三次尝试会乘法放大总调用量。', '压测并注入依赖慢，确认核心流量p99、拒绝率和资源占用仍在目标范围。', 'https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/');
put('microservices-11', '微服务治理把部署、健康、配置、契约、监控与恢复串成闭环。独立服务应能独立演进，不意味着可忽略共享Schema和消费者版本。', '构建可追踪镜像并检查接口兼容。¦按就绪与滚动策略接入流量，观察新版本错误。¦配置、数据库和事件格式采取兼容演进，回滚需可运行旧版本。', '事件v1：employeeId,username\n事件v2：增加optional displayName\n先升级消费者兼容v1/v2\n再发布生产者v2，最后评估删除旧字段', 'plaintext', '服务独立部署时治理必需；单体同样要版本、健康与回滚，不以服务数判断成熟度。', '回滚代码不恢复已删除数据；未知字段兼容也不覆盖字段语义改变。', '混合新旧版本演练、失败发布自动停止、回滚后读取新数据与消费旧事件均通过。');

put('testing-1', '单元测试验证较小行为的契约，JUnit5提供执行与断言机制。有效测试必须在错误实现时失败，且覆盖关键规则而非照抄实现。', '准备明确输入与协作环境。¦调用被测规则，断言结果、异常或必要状态。¦选择边界和反例，保持每个失败能解释违反了哪条契约。', '@Test\nvoid negativeQuantityIsRejected() {\n  assertThrows(IllegalArgumentException.class,\n      () -> Calculator.total(List.of(-1)));\n}', 'java', '纯规则和小行为用单元测试反馈快；真实SQL或事务不能只靠单元Mock验证。', '100个几乎相同成功用例不等于覆盖风险。测试类名和断言应围绕行为而非私人方法顺序。', '故意删除校验，测试必须失败；加入0、最大值、空输入等规则所需边界。', 'https://junit.org/junit5/docs/current/user-guide/');
put('testing-2', '集成测试让组件与真实依赖协同执行；Testcontainers管理测试容器，减少本机环境差异。它能验证SQL方言、约束和连接，但需要可运行容器环境。', '启动与项目兼容的数据库容器并应用迁移。¦将连接参数注入应用，执行真实Mapper/Service。¦断言数据库状态，清理隔离数据，再覆盖并发和失败。', '@Container\nstatic MySQLContainer<?> mysql =\n    new MySQLContainer<>("mysql:8.4");\n// 使用测试容器真实连接执行：\n// 并发create相同username → 一成功、一409；库内只一行', 'java', '数据访问与事务必须有集成测试；纯算法无需数据库容器。镜像标签按团队复现策略固定。', 'mysql:8.4主版本标签仍可更新；测试并不自动模拟生产数据量、复制和硬件。', '验证唯一键、回滚、隔离与迁移；故意移除唯一约束，并发测试应揭示重复记录。', 'https://java.testcontainers.org/modules/databases/mysql/');
put('testing-3', 'Mockito提供依赖替身，设置返回与异常，隔离被测业务。verify能验证有意义的协作，但Mock不能证明真实依赖语义。', '把外部接口注入被测Service。¦stub限定场景，如供应商超时。¦断言业务选择待处理或失败，并验证必要协作而非所有内部调用。', 'Notifier notifier = mock(Notifier.class);\ndoThrow(new TimeoutException()).when(notifier).send(any());\n// 被测类型和方法需声明相容异常\n// 调用后断言任务仍处于可重试状态，而不是假称已发送', 'java', '外部API失败分支用Mock可稳定复现；数据库锁和真实事务要用集成环境。', 'checked异常必须与方法签名兼容。大量verify调用顺序会使正常重构破坏测试。', '替身抛异常时确认业务结果和状态；再用真实供应商契约测试弥补Mock假设。', 'https://javadoc.io/doc/org.mockito/mockito-core/latest/org/mockito/Mockito.html');
put('testing-4', 'MockMvc通过MVC基础设施模拟HTTP处理，验证路由、解析、校验和响应；真实端口测试另外覆盖容器、网络与代理。测试切片加载范围需明确。', '配置所需Controller、Advice、转换器与安全设施。¦构造Method、Path、Header与Body。¦断言状态和JSON，失败场景确认业务未执行或已回滚。', 'mockMvc.perform(post("/employees")\n    .contentType(MediaType.APPLICATION_JSON)\n    .content("{\"username\":\"\"}"))\n  .andExpect(status().isBadRequest());\n// 安全配置要求时先提供合法测试身份及CSRF', 'java', 'Controller契约适合MockMvc；部署代理路径和TLS需真实端到端联调。', '若实际先401/403，不能把断言400错误归因校验；安全与校验有执行顺序。', '合法认证+非法Body验证400，缺认证验证401，真实网络另验证代理转发路径。', 'https://docs.spring.io/spring-framework/reference/testing/mockmvc.html');
put('testing-5', '端到端测试从用户可见操作贯穿前后端和数据，验证完整用例。它最接近业务验收，但较慢且易受环境、数据与等待影响。', '准备隔离测试账号和唯一数据。¦操作页面并等实际网络/界面条件，不靠固定sleep。¦刷新或重新读取确认持久状态，再清理本次测试数据。', '操作：管理员登录 → 新增唯一username → 保存\n断言：成功提示 + 列表出现员工\n刷新：该员工仍存在\n权限：普通用户无法执行同样操作', 'plaintext', '核心少量路径用E2E；全部边界都靠浏览器跑会慢，分层测试更合理。', '只看到toast成功不证明落库。测试应防环境误连与数据污染，网络失败重试不得重复业务。', '让后端写入失败，E2E不得仍成功；刷新检索、权限和重复提交分支独立验证。');
put('testing-6', 'JaCoCo根据字节码执行记录覆盖信息，行与分支覆盖提示未执行区域。覆盖率是测试执行范围，不是断言准确率或正确性证明。', '测试运行采集执行数据。¦报告映射到类与源码，检查关键失败分支。¦补充能杀死错误实现的断言，而不只为了数字调用方法。', '被测规则：if(stock <= 0) reject; else reserve;\n只有stock=10：成功路径执行，但拒绝分支未验证\n加入stock=0：断言不扣减、不建订单\n覆盖率只是发现缺口的辅助', 'plaintext', '用报告检查关键风险是否未测；纯样板getter不必为百分比添加无意义测试。', '同一行包含多个条件，行覆盖可能隐藏未覆盖分支。生成代码和编译版本影响报告。', '删除库存拒绝规则，测试必须失败；把覆盖数据与业务风险矩阵交叉检查。', 'https://www.jacoco.org/jacoco/trunk/doc/');
put('testing-7', '回归测试重复检查已承诺行为，防止改动破坏旧功能。历史故障应转成针对根因的可复现测试，不是无限叠加整站点击。', '列出变更影响的共享配置、数据和接口。¦运行风险相关的规则、接口和集成测试。¦重要历史缺陷固定输入与断言，发布再做核心冒烟。', '修改Jackson时间格式后回归：\n员工创建响应时间、列表时间、导出时间\n旧客户端Schema、异常响应\n历史问题：跨时区日期边界', 'plaintext', '频繁迭代需要自动化回归；执行范围随风险选择，不能每次无限重复无变化检查。', '测试通过依赖测试有效且环境相关；过期断言可能反而冻结错误行为。', '重放历史故障输入，确认旧版本失败新版本通过；观察共享配置变更的影响范围。');
put('testing-8', '性能测试测目标负载，压力测试寻找过载边界，稳定性测试看长时间资源与恢复。到达率、并发、结果混合和数据规模要明确定义。', '建立生产近似的请求分布与数据集。¦逐步增负载观测吞吐、p95/p99、错误、池等待与DB。¦长时间和故障注入看内存增长、积压、恢复，不仅峰值QPS。', '场景：80%读、15%创建、5%导出\n到达率：20→50→100 req/s，每级稳定观察\n记录：完成吞吐、错误率、p99、DB等待\n结束：停负载，队列与连接占用应恢复', 'plaintext', '容量和上线风险需要性能证据；微基准只适合隔离小操作，不可直接推算系统吞吐。', '闭环固定并发压测可能隐藏等待期间的新到达。成功请求p99也不能掩盖大量超时。', '报告负载、时间窗口、数据量与失败比例；重复相同场景比较变更前后而非只报最好一次。');

put('devops-1', 'JAR是Java制品，Linux运行进程，Shell组织命令，systemd管理服务生命周期与日志。可靠部署应有明确用户、配置、退出和恢复，而非只让终端不关闭。', '用受限服务用户取得固定制品和配置。¦启动JVM并检查就绪、端口与日志。¦systemd管理退出重启，但业务健康和资源仍需监测。', '[Service]\nUser=employee\nWorkingDirectory=/opt/employee\nExecStart=/usr/bin/java -jar /opt/employee/app.jar\nRestart=on-failure\n# systemd片段；路径和JDK须按环境确认', 'plaintext', '单主机部署可用systemd；容器平台已有生命周期管理时避免互相嵌套不必要守护进程。', '进程存在不等于HTTP正确。无限重启可掩盖配置错误，也可能反复放大启动负载。', '停止进程检查策略，验证日志、信号退出、权限与端口；请求真实健康和业务冒烟接口。', 'https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html');
put('devops-2', 'TLS通过证书验证身份并协商加密；Nginx可作为TLS终止与代理入口。浏览器到代理、代理到应用是两个连接区段，需要各自信任与传输策略。', '客户端验证证书域名、有效期与可信链。¦代理解密并按路由转发；内部是否再TLS由风险与拓扑决定。¦应用只信任已知代理提供的scheme和客户端地址信息。', 'server {\n  listen 443 ssl;\n  server_name api.example.test;\n  ssl_certificate /etc/nginx/fullchain.pem;\n  ssl_certificate_key /etc/nginx/private.key;\n  location / { proxy_pass http://employee_app; }\n}', 'nginx', '公网传输通常需要HTTPS；本地实验可HTTP但不能把它当生产安全方案。', '证书和密钥要真实配置且保护；TLS不修复SQL注入、越权或泄露日志。TCP本身不加密。', '验证域名、过期证书、代理上游异常；检查外部HTTPS与应用生成URL的scheme一致。', 'https://nginx.org/en/docs/http/configuring_https_servers.html');
put('devops-3', 'Docker镜像封装文件系统与入口，容器运行隔离进程；Compose描述一组本机服务。持久数据需要卷与备份，镜像不是数据库备份。', '构建镜像放入固定JAR并指定入口。¦运行注入环境与资源限制，发布端口。¦数据库卷独立于可替换容器，服务间网络名称由平台提供。', 'FROM eclipse-temurin:21-jre\nWORKDIR /app\nCOPY app.jar app.jar\nENTRYPOINT ["java","-jar","app.jar"]\n# 实际供应链可固定镜像digest，并使用受限用户', 'plaintext', '多环境统一制品可容器化；简单本地运行不强制Docker，也不能用容器代替资源规划。', '容器仍使用宿主资源，限制与JVM内存需协调。latest或浮动标签不保证内容固定。', '重建新容器验证外部卷数据仍在；检查退出信号、内存限额、端口映射与镜像版本。', 'https://docs.docker.com/get-started/docker-concepts/');
put('devops-4', 'Kubernetes持续协调声明状态，Deployment管理副本更替，Service提供流量访问；探针区分启动、存活与就绪。它管理进程，不自动保证业务数据正确。', 'Scheduler将Pod安排到可用节点并启动容器。¦readiness决定是否接入服务流量，liveness失败可触发容器重启。¦控制器维护副本并按滚动策略替换，需资源和终止设计。', 'readinessProbe:\n  httpGet: {path: /actuator/health/readiness, port: 8080}\n  periodSeconds: 5\n# 示例片段；端点暴露和实际就绪语义必须配置\n# 不能把所有外部依赖故障都放进liveness', 'yaml', '多服务与平台运维需求适合Kubernetes；小单机应用不必只为使用云原生而增加集群。', '错误liveness可能在数据库故障时重启全部应用；readiness也不能自动覆盖所有真实业务。', '模拟启动慢、依赖故障、实例终止，观察流量退出、重启和进行中请求处理。', 'https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/');
put('devops-5', 'CI验证变更可集成，CD把可追踪制品按策略交付或发布；GitHub Actions与Jenkins是执行平台。构建、审批、部署和验证应各有证据。', '提交触发构建与测试，固定工具链和依赖。¦生成带提交标识的不可变制品并保存。¦部署同一制品，检查健康与业务指标，失败停止或回滚。', '提交SHA → 编译+测试 → 镜像digest\n测试环境部署digest → 冒烟\n生产灰度相同digest → 指标检查\n失败：停止扩流量，回滚旧digest', 'plaintext', '持续交付项目需要自动流水线；简单实验可人工运行相同步骤，但仍保留版本对应。', 'CI绿色不保证未测试场景正确。部署权限与秘密应最小化，依赖脚本也可能影响供应链。', '确认运行版本与测试制品digest一致，注入失败测试应阻断部署；演练回滚。', 'https://docs.github.com/en/actions');
put('devops-6', 'ELK常指Elasticsearch、Logstash、Kibana；EFK用Fluentd等采集组件替代部分角色。日志集中后才能跨实例检索，但采集、解析与权限决定证据质量。', '应用输出结构化事件，采集器读取并缓冲。¦解析字段、脱敏并送存储索引。¦按requestId与时间关联，设置保留、查询权限和采集失败监控。', '{"time":"2026-10-13T08:00:00Z",\n "service":"employee", "requestId":"r-42",\n "event":"employee_created", "employeeId":108}\n// 不含token、password、身份证明文', 'plaintext', '多实例或频繁排错需集中日志；小实验可先看本地日志，保持格式一致便于迁移。', '时钟偏差、异步写入和丢失可能打乱时间线；“没搜到日志”不能独立证明没执行。', '模拟采集后端故障，检查缓存与丢失告警；按requestId能拼出真实请求链。');
put('devops-7', 'Prometheus抓取时间序列指标，Grafana展示与告警。指标应表达流量、错误、延迟和饱和，标签维度要有限，尾延迟不能用平均代替。', '应用与组件导出counter、gauge、histogram等。¦抓取存储后计算速率、分布与跨实例聚合。¦按SLO设置告警，链接部署事件与诊断证据。', '# 示例PromQL，指标名与bucket标签需实际埋点支持\nrate(http_requests_total{status=~"5.."}[5m])\nhistogram_quantile(0.99,\n  sum by(le)(rate(http_duration_seconds_bucket[5m])))', 'plaintext', '运行SLO与容量判断需要指标；用户id、订单id不适合作为无限指标标签。', 'p99不能简单平均多个实例的p99。直方图精度受bucket影响；低样本时分位值需谨慎。', '制造已知5%错误和慢请求，检查图表、聚合与告警时间；观察指标基数和抓取失败。', 'https://prometheus.io/docs/practices/histograms/');
put('devops-8', 'OpenTelemetry定义遥测API、SDK与传播和导出机制，Collector接收处理转发；存储分析由具体后端承担。它关联观察信号，不是数据库或监控UI。', '自动或手动埋点创建span、metric和log关联。¦跨HTTP/MQ传播context，配置采样与敏感属性。¦Collector批处理导出，监测导出失败与资源开销。', 'try (Scope scope = span.makeCurrent()) {\n  mapper.insert(employee);\n} catch (RuntimeException ex) {\n  span.recordException(ex);\n  throw ex;\n} finally { span.end(); }\n// span由已配置Tracer创建，示例展示生命周期', 'java', '统一多语言多服务观察时有价值；已有成熟单服务指标不必重复埋点造成双计数。', '开启Agent不代表业务事件、MQ父子关系全部正确。采样会丢弃部分请求细节，秘密不能放属性。', '跟踪已知请求检查父子span与跨消息关联，断导出器验证应用不被无限缓冲拖垮。', 'https://opentelemetry.io/docs/');
put('devops-9', '可观测性通过输出推断内部状态；日志讲事件，指标讲趋势，trace讲某请求关联。环境版本与配置是解释变化的重要上下文。', '从用户症状与影响范围提出假设。¦对齐错误、延迟、资源和发布时间，查对应请求。¦用最小实验或变更验证假设，记录剩余不确定性。', '症状：p99变慢，错误少\n证据：SQLspan长、DB锁等待升高、CPU低\n候选：长事务持锁\n验证：找到阻塞事务，解除后观察等待与p99恢复', 'plaintext', '复杂故障需多信号交叉验证；一个仪表盘绿色不能替代业务验收。', '相关性不是因果。缺采样、不同时间窗与未记录配置会导致错误推断。', '用已知故障盲测排查流程，确认能定位且没有只凭猜测重启或调池。');
put('devops-10', '蓝绿在两套环境间切流量，灰度逐步给新版本流量，滚动逐实例替换。版本混跑、数据兼容与回滚路径决定风险，不只是换容器。', '新版本先兼容旧Schema和旧消费者。¦小流量或部分实例观察错误与业务指标。¦扩量前验证，失败回旧代码，但数据变更需独立恢复策略。', '发布1：新增nullable列（旧代码可运行）\n发布2：新代码兼容旧值并逐步写新列\n发布3：回填和验证\n发布4：所有版本不再依赖旧列后才收缩', 'plaintext', '影响大或频繁发布用分阶段策略；一次性小本地demo无需复制多环境。', '蓝绿不能自动回滚已删除数据；灰度流量必须具有代表性，粘性会影响采样。', '同时运行旧新版本，注入失败后回滚，检查新数据还能被旧代码读取。', 'https://kubernetes.io/docs/concepts/workloads/controllers/deployment/');

put('jvm-1', '类型身份由类名与定义它的加载器共同确定。双亲委派是常见加载策略，用于先请求父加载器；实际加载器可为隔离或应用服务器采用不同策略。', '加载器查已加载类型并按其策略委派或查字节码。¦定义类后进行链接、准备、解析和初始化相关步骤。¦同名类在不同定义加载器下可互不兼容，涉及插件与重部署。', 'Class<?> c = Employee.class;\nSystem.out.println(c.getName());\nSystem.out.println(c.getClassLoader());\n// 同类名由两个独立定义加载器加载，Class对象可不同', 'java', '插件、服务器重部署和依赖冲突需分析加载器；普通业务先确保依赖树正确。', '双亲委派不是所有加载器都无例外遵守。调用Class.forName可能触发初始化，行为依重载参数。', '打印运行类加载器与代码来源，构造两个加载器验证同名类转换失败原因。', 'https://docs.oracle.com/javase/specs/jvms/se21/html/jvms-5.html');
put('jvm-2', 'JVM规范描述堆、方法区、运行时常量池、线程栈等运行区域；对象与栈帧职责不同。HotSpot的元空间等是实现选择，优化可消除某些分配。', '调用方法创建栈帧以保存局部与执行状态。¦对象分配及引用关系形成可达图，局部变量可持对象引用。¦对象存活与GC受引用影响，JIT可能优化分配但不改变程序可观察语义。', 'Employee dto = new Employee();\nEmployee alias = dto;\nalias.setName("小智");\n// 两局部引用同一对象，不是两个Entity\n// 不能仅因变量是局部就断言对象一定在栈', 'java', '解释内存与泄漏需区分引用、对象和执行帧；不必从代码表面猜HotSpot每个对象布局。', '方法区是规范概念，不直接等于某一代HotSpot固定实现。StackOverflowError与堆OOM原因不同。', '用堆转储查看对象引用，递归实验观察栈错误；对照JVM参数限制的不同区域。', 'https://docs.oracle.com/javase/specs/jvms/se21/html/jvms-2.html');
put('jvm-3', 'GC按可达性管理对象回收，回收器在吞吐、暂停和资源之间取舍；GC日志记录阶段、原因与占用。不同JDK/发行版可用回收器和默认不同。', '分配增加使用量，GC处理不可达对象。¦部分阶段暂停应用线程，部分可并发执行并消耗CPU。¦日志与请求时间关联后，继续看分配速率、存活集和回收效果。', 'java -Xms512m -Xmx512m \\\n  -Xlog:gc*:file=gc.log:time,uptime,level,tags \\\n  -jar app.jar\n# shell换行写法按操作系统调整', 'plaintext', '已证实GC影响SLO时调内存、分配或回收器；不能只因听说某回收器延迟低就全盘替换。', '日志停顿与业务延迟存在重叠不等于全部因果；加堆也可能延长部分回收并增加资源成本。', '比较相同负载下暂停分布、吞吐、CPU和存活集，确认改动没有转移瓶颈。', 'https://docs.oracle.com/en/java/javase/21/gctuning/');
put('jvm-4', 'OOM表示某资源无法继续分配，不一定仅是Java堆；泄漏是业务已不需要却仍被保留的资源。堆、元空间、直接内存和线程等需分开诊断。', '看具体错误消息、容器限额与JVM参数。¦收集适当堆/线程/原生内存证据，定位增长来源。¦修复保留或泄漏，再评估容量；保留转储本身也占磁盘并含敏感数据。', 'java -Xmx512m \\\n  -XX:+HeapDumpOnOutOfMemoryError \\\n  -XX:HeapDumpPath=/var/diag/app.hprof \\\n  -jar app.jar\n# 路径必须有权限和容量，转储含敏感对象', 'plaintext', '内存事故按区域诊断；增加上限可暂时恢复但不应替代根因分析。', '容器被OOM killer终止可能没有Java堆错误。无界缓存保留对象与瞬时高分配是不同问题。', '长期负载下GC后存活量趋势、引用支配树、线程数和原生占用交叉验证。', 'https://docs.oracle.com/en/java/javase/21/troubleshoot/troubleshoot-memory-leaks.html');
put('jvm-5', 'Arthas在运行Java进程中观察线程、类和方法，帮助核对实际运行代码及耗时。诊断本身可有开销，范围与敏感数据应受控。', '确认目标PID与权限，连接正确进程。¦查看线程和类来源，缩小方法范围。¦有限次数观测方法耗时/输入，结束后清理诊断影响。', 'dashboard\nthread\nsc -d com.example.EmployeeService\ntrace com.example.EmployeeService create -n 5\n# 生产先评估范围、开销与敏感输出', 'plaintext', '线上行为难本地复现时适用；已有trace可解释时无需高频动态插桩。', '代理与重载会影响定位，watch参数可能泄露秘密。诊断成功不代表性能改动已验证。', '只观察少量调用并对比指标，确认无明显额外延迟；核对类实际加载路径与发布SHA。', 'https://arthas.aliyun.com/en/doc/');
put('jvm-6', 'JProfiler与VisualVM分析CPU、线程、内存与引用；采样以统计方式找热点，插桩有更高细节但可能改变运行成本。工具视图需对应业务负载。', '选择可代表问题的负载和采集窗口。¦查看热点栈、分配或阻塞线程，判断计算还是等待。¦用具体优化后相同负载复测，不只保存最漂亮截图。', 'CPU热点：passwordEncoder.matches → 频繁认证\n分配热点：大列表JSON → 一次性加载过多\n等待热点：JDBC → 继续看DB锁和池等待\n引用保留：static Map → 缓存无上限', 'plaintext', '瓶颈不清时选相应分析工具；生产是否允许接入按权限、开销与数据要求确认。', 'wall-clock时间和CPU时间不同。Profiler可能影响被测系统，采样也可能遗漏极短调用。', '验证采集开销，对比基线；热点优化后确认端到端p99与吞吐真实提升。', 'https://visualvm.github.io/');
put('jvm-7', '性能优化是带目标、证据和对照的改进循环，必须说明负载与限制。最快局部算法不一定改善整个请求，优化也可能损害正确性和成本。', '定义吞吐、尾延迟、错误与资源目标，建立基线。¦定位主要耗时或饱和，提出可检验假设。¦一次改变关键变量，同负载验证结果与副作用，记录边界。', '基线：p99=800ms，DB等待占主要耗时\n假设：缺索引导致扫描\n改动：增加经验证复合索引\n复测：p99、扫描行、写成本、池等待均记录', 'plaintext', '有SLO缺口或成本问题时优化；没有瓶颈证据不要随机更改池、堆和缓存。', '平均改善不保证p99改善；只报成功样本会遗漏超时。瓶颈解除后可能转移。', '保留同数据、同请求混合、同资源的改前改后报告，检查正确性回归和失败比例。');

put('design-1', '创建型模式安排对象构造，结构型安排对象组成，行为型安排对象协作。模式名称应对应真实变化问题，不能只为目录好看而套用。', '找变化：通知供应商不同但业务所需动作一致。¦Adapter转换供应商接口，Factory选择实现，Strategy表达可替换规则。¦调用方依稳定契约，新增实现不修改核心流程。', 'interface Discount { BigDecimal apply(BigDecimal amount); }\nclass NoDiscount implements Discount {\n  public BigDecimal apply(BigDecimal a) { return a; }\n}\n// Strategy：调用方接收Discount，不判断具体子类名称', 'java', '复杂构造、外部接口差异与可替换规则确实出现时使用；简单单实现不必先造工厂。', '模式不是性能或可维护性的天然保证。过多抽象可能让真实调用更难追踪。', '加入第二种规则时观察核心调用是否保持不变，契约测试对两实现均通过。');
put('design-2', 'MVC划分展示相关职责，分层架构划分协议、业务、数据依赖。常见六原则通常指单一职责、开闭、里氏替换、接口隔离、依赖倒置与迪米特原则，需在场景中权衡。', '职责由变化原因划分，不只是按代码行数。¦稳定接口控制依赖，让替换实现仍遵守契约。¦限制穿透式访问，避免Controller知道数据库细节或巨大对象内部结构。', 'Controller → EmployeeUseCase\nEmployeeUseCase → EmployeeRepository接口\nMyBatisRepository implements EmployeeRepository\n方向：业务表达需求，基础设施实现它', 'plaintext', '系统变化和团队协作需要清晰边界；六原则是评估工具，不是要求每类只有一个方法。', '开闭不是代码永不能改；里氏替换关心行为契约。MVC模型也不是所有Service和Mapper的别称。', '更换存储实现并跑同用例测试；检查新增规则是否只在一个清晰位置改动。');
put('design-3', '面向对象设计围绕职责、状态与不变量，让对象协作完成用例。只有getter/setter的数据容器未必足够表达复杂状态规则。', '写出订单可取消的前置状态。¦把状态转换集中在明确方法中，非法转换立即拒绝。¦应用服务组织存储、授权和事务，实体负责自身规则。', 'class Order {\n  private Status status;\n  void cancel() {\n    if (status != Status.PENDING) throw new IllegalStateException();\n    status = Status.CANCELLED;\n  }\n}', 'java', '状态与规则复杂时封装行为；简单CRUD数据可保持轻量，避免强造贫血/充血术语之争。', '对象方法检查内存状态不自动处理数据库并发；保存仍需版本条件或锁与事务。', '测试每种状态转换，再让两个事务修改同订单验证持久层冲突处理。');
put('design-4', 'DDD以领域模型组织规则，CQRS区分命令写模型和查询读模型，事件驱动传递已发生事实。CQRS不要求两个数据库，事件也不是“请做某事”的命令。', '命令CreateEmployee验证规则并写权威模型。¦提交后发布EmployeeCreated事实，消费者构建读模型。¦查询读取所需展示视图，明确派生延迟与恢复。', 'Command: CreateEmployee(username,name)\nWrite model: 员工唯一性、权限、状态\nEvent: EmployeeCreated(eventId,employeeId)\nRead model: EmployeeDirectoryView\nQuery: SearchEmployees(keyword)', 'plaintext', '复杂写规则与复杂读取形状差异大时有用；简单单表CRUD不必引入独立读库和事件重建。', '命令可能被拒绝，事实事件不应伪称未发生操作已完成。事件模式增加版本、幂等与积压管理。', '停止读模型消费者后验证写入仍正确，恢复后事件重放能完整收敛且不重复效果。');
put('design-5', '六边形架构用端口表达业务需要、适配器连接HTTP/数据库等外部技术；整洁架构强调依赖朝稳定核心。目的在保护规则而非复制一套复杂目录。', '用例定义输入与业务结果，外部框架不是规则前提。¦持久端口表达保存/查询需求，MyBatis适配器实现。¦REST和批量导入适配器都调用同用例，不绕过核心规则。', 'interface EmployeeRepository { long save(Employee employee); }\nclass CreateEmployee {\n  private final EmployeeRepository repository;\n  CreateEmployee(EmployeeRepository r) { repository=r; }\n  // 校验规则后调用repository.save\n}', 'java', '多入口、长期替换与测试隔离需求显著时采用；简单项目可用常规分层达到足够清晰。', '“核心无框架”不意味着没有依赖；需要确定事务如何包用例，防止适配器各自提交破坏边界。', '用内存适配器测试规则，再用真实MyBatis适配器测试契约和事务；两入口结果一致。');
put('design-6', '高可用关注正确服务在故障中持续提供，高并发关注同时在途工作，高性能关注延迟、吞吐和资源成本。三个目标相关，但不能互相证明。', '定义可用性SLO和允许失败方式。¦测流量与在途数量，评估真正瓶颈资源。¦用冗余、容量和恢复验证故障，防止应用多实例仍依赖单点数据。', '系统A：1000在途、每请求10秒 → 并发高，体验可能差\n系统B：100请求/s、每请求50ms → 平均约5在途\n可用：主实例故障后错误预算与恢复时间仍达标', 'plaintext', '按业务SLO投资冗余与优化；不能只为宣称高并发堆积大量等待请求。', '多副本应用不自动解决数据库单点；吞吐提高也可能来自丢弃请求，必须同时看错误和正确性。', '容量测试加节点故障演练，记录成功吞吐、p99、错误与恢复时间。');
put('design-7', '扩展性让容量或功能增长有可控路径，可维护性让团队理解与修改成本合理，安全设计限制不可信输入和权限。质量取舍必须可说明。', '先标出预计变化与风险，而非实现所有未来可能。¦用稳定契约、数据边界和最小权限控制影响。¦新增能力后检查回归、运行成本与排错路径。', '新增短信供应商：实现Notifier适配器\n新增租户：可信tenantId进入授权和查询\n新增实例：会话外部化、任务幂等、总连接预算\n每变化都对应具体边界', 'plaintext', '需要可持续增长的项目应设计关键变化点；预留所有功能反而可能损害维护性。', '配置可变不代表安全可随意改变；抽象和中间件本身也有学习、运行和故障成本。', '让另一开发者依据文档实现一项变化，测修改范围、测试覆盖与错误反馈清晰度。');
put('design-8', '多租户保证客户数据隔离，读写分离扩大读取能力，分片拆分数据容量。隔离、路由与容量是不同维度，组合后必须保留授权。', '认证上下文确定可信tenantId。¦所有查询、修改、导出与搜索包含租户范围。¦分片路由按数据拥有规则定位，唯一键按业务范围设置。', 'SELECT id,username FROM employee\nWHERE tenant_id=? AND id=?;\nCREATE UNIQUE INDEX uk_tenant_username\nON employee(tenant_id,username);\n-- tenantId不能只取客户端Body', 'sql', 'SaaS需明确租户隔离；容量没有证据前无需先分库分表。读副本选择还要满足一致性。', '漏加租户的导出、缓存key和后台任务同样会越权；多租户不意味着必须每租户独立数据库。', '相同id跨租户访问必须拒绝；检查缓存key、搜索和批量操作都有一致租户边界。');
put('design-9', '一致性治理定义哪些数据权威、哪些可延迟，以及出现差异怎样发现与修复。监控必须覆盖传播积压、失败与实际数据对账。', '业务写与Outbox在同事务提交。¦发布与消费记录可重试状态和幂等标识。¦指标观察最老未处理年龄，对账验证没有事件丢失或永久差异。', 'outbox_oldest_pending_age_seconds = now - oldest.createdAt\n目标：低于约定同步时限\n异常：消费永久失败 → 死信+告警\n修复：重放事件或按权威数据重建派生视图', 'plaintext', '有缓存、搜索和异步支线时必须明确治理；单库本地事务也需验证并发不变量。', '队列长度为0不证明数据一致，可能事件根本没发出。监控应覆盖业务源和传播链。', '删除一条派生记录进行对账演练，确保能发现并恢复；模拟Outbox发布失败。');

put('architect-1', '需求分析把用户目标转为可验收用例与约束，系统设计再组织组件和数据实现目标。技术图不是需求的替代。', '确认参与者、权限、操作和失败体验。¦给出规模、延迟、一致性、恢复与安全约束。¦从稳定主链设计最小可交付方案，再按证据扩展。', '用例：管理员新增员工\n规则：租户内username唯一、审计操作者\n结果：创建已提交；邀请允许异步\n失败：400/401/403/409及可恢复通知任务\n验收：并发同名只一个成功', 'plaintext', '方案讨论先固定约束，避免团队围绕产品名争论；未知规模需标假设并验证。', '“支持高并发”不是验收标准；需要流量模型、成功定义与时间窗口。', '把需求转成可执行成功/失败用例，业务方可判断是否达到预期。');
put('architect-2', '选型比较适配、代价和团队能力，演进控制迁移风险，拆分调整边界。合理方案解释为什么现在需要，以及不采用时会怎样。', '获取瓶颈或变化成本的真实证据。¦比较候选和保持现状，包含运维、迁移与失败成本。¦逐步实施并设验证和回退条件，避免一次全盘重写。', '问题：报表拖慢在线CRUD\n候选A：优化查询；B：独立任务资源；C：拆报表服务\n比较：收益、数据同步、运维、成本\n验证：在线p99与报表完成时间同时达标', 'plaintext', '问题足够具体时选型；没有需求和证据可先保留简单方案。', '技术流行和团队熟悉都不是唯一标准；迁移期间双写和新旧混跑也要设计。', '建立决策记录、原始基线和可撤回实验；达到目标后才扩大迁移。');
put('architect-3', '容量评估把到达率、服务时间、工作量与资源限制联系起来；服务治理管理调用契约与故障影响。Little定律L=λW适用于稳定平均系统关系。', '定义成功请求、到达/完成范围和稳定观察窗口。¦用平均时间估计在途量，再观察尾部、突发与各瓶颈。¦限制并发和队列，验证扩实例不会压垮共享数据库。', 'λ = 100 requests/s\nW = 0.2s（系统内平均总时间）\nL ≈ 20（平均在途，不是最佳线程数）\n若SQL并发由8条连接限制，需另测SQL服务时间与排队', 'plaintext', '规划规模或配置资源时使用模型加压测；模型指导问题，不直接替代实验。', '未稳定积压增长时不能简单用λW给安全容量；平均关系不直接保证p99或故障冗余。', '对照测到的在途平均量与λW，记录定义和误差；再做突发及一节点故障验证。');
put('architect-4', '事故处理先限制影响与恢复，再复盘事实、促成条件和改进。复盘目的让系统更易检测、隔离与恢复，不是只找一个人背责。', '确认受影响用户、功能和开始时间，保存证据。¦采取可控止损，如回滚、限流或隔离，观察业务恢复。¦建立事件时间线，区分事实与假设，落实验证改进。', '10:02 发布v17\n10:04 DB等待升高，p99恶化（证据）\n10:08 回滚v16，等待恢复\n根因候选：新查询长事务\n后续：复现、缩事务、告警、发布验证', 'plaintext', '生产事故要有协作和时间线；低风险本地错误也可保留重现与修复测试。', '回滚相关性不自动证明唯一根因，重启恢复也不是完整解释；证据缺失需坦诚保留。', '在测试环境复现促成链，修复后同场景不再出现并验证告警提前发现。');
put('architect-5', '稳定性建设持续控制资源、变更和恢复风险；安全合规围绕数据、身份和适用要求形成具体控制。规则适用范围需按实际组织和场景确认。', '列故障模型：DB、MQ、磁盘、依赖、发布。¦为每模型设隔离、恢复目标与观测。¦数据分类后最小权限、脱敏、保留与审计，定期演练验证。', '演练：MQ停30分钟\n预期：员工创建仍正确；通知待发、积压告警\n恢复：限速消费，避免重试风暴\n数据：事件不包含原始密码和无必要身份证', 'plaintext', '上线系统需要稳定性与数据保护；控制应针对真实风险，不是堆积无关工具清单。', '备份存在不证明可恢复；安全检查完成不证明无漏洞，需实际权限和恢复测试。', '定期还原备份、故障注入和授权测试，记录达到的RTO/RPO及未覆盖风险。');
put('architect-6', '协作让需求、责任与风险可共享，Code Review检查行为、边界与证据。评审价值在发现难由个人或自动工具看到的问题。', '改动说明具体问题、行为变化和验证。¦评审沿调用链检查权限、事务、并发、失败与兼容。¦讨论明确且可执行，重要结论落入测试或文档。', '评审新增员工：\n1. operator来源可信吗？\n2. 唯一约束存在吗？\n3. 员工与角色是否同事务？\n4. 响应失败重试怎样处理？\n5. 日志是否泄露个人信息？', 'plaintext', '多人长期维护需评审，自动格式化承担样式；简单可逆改动按风险简化流程。', '评审通过不是运行正确性保证；不能只挑命名忽略并发竞态。', '用历史缺陷检验评审清单能否发现，检查评论是否对应可验证规则而非个人风格。');
put('architect-7', '工程文档记录契约、运行事实与决策，项目管理把目标拆成可验收交付。文档需要版本、责任与证据，否则很快变成误导草图。', '描述用例、接口、Schema和错误契约。¦把任务按结果与依赖拆分，明确验收证据。¦发布更新运行与恢复文档，记录技术决策原因和限制。', 'ADR：员工通知异步化\n背景：供应商慢影响事务\n选择：Outbox+幂等消费者\n代价：通知延迟、积压运维\n验证：故障不拖创建；事件最终完成\n版本：对应提交SHA与Schema迁移', 'plaintext', '团队协作与交接需要最小有效文档；没有变化和责任的大量复制说明维护成本高。', '计划描述未来，架构报告描述当前，两者必须区分。文档中命令与地址也可能过期。', '新成员按文档在干净环境运行和排错，确认链接、命令、版本与实际行为一致。');
put('architect-8', '质量、业务、成本和表达决定技术收益能否兑现。成本包含机器、研发、迁移、运维和事故，正确表达必须说明范围与证据。', '先确定哪种失败对业务可接受。¦比较方案总成本和获得的质量目标。¦用问题、取舍、验证和限制解释结果，避免产品名堆砌。', '业务取舍：创建需实时正确，短信可延迟\n方案：本地事务+Outbox\n成本：多任务状态与监控\n收益证据：模拟短信故障不影响创建；积压可恢复\n限制：不能承诺所有通知即时送达', 'plaintext', '跨团队方案需用共同可理解的目标表达；不是越复杂越像架构师。', '模拟测试收益不能冒充真实生产指标。节省服务器但增加巨大事故风险未必降低总成本。', '由业务和运维分别复述接受的状态与恢复路径，确认没有用术语掩盖差异。');

put('interview-1', '基础题应以条件、执行步骤和反例证明语言机制。集合、并发、JVM题只有明确单线程、共享状态、内存模型与版本才能给可靠结论。', '先说保证范围，如volatile只针对特定读写可见与顺序。¦拆count++为读、计算、写，推演两线程同读0后都写1。¦提出AtomicInteger或同锁方案，并说明多实例另需数据层保护。', 'volatile int count = 0;\n// T1读0 → T2读0 → T1写1 → T2写1\n// 两次++结果可能仅1\nAtomicInteger atomic = new AtomicInteger();\natomic.incrementAndGet();', 'java', '用小可推演反例准备高频题，再映射真实项目；不要只记关键词。', '一次运行得到正确值不证明无竞态；并发示例输出可多种合法结果。', '重复多线程测试与规范推理交叉验证，明确Atomic只解决该单变量更新。', 'https://docs.oracle.com/javase/specs/jls/se21/html/jls-17.html');
put('interview-2', 'Spring题的核心是执行者、代理边界与生命周期：谁读取注解、调用是否经过它、失败由哪层处理。不能把某旧版本简答套成绝对结论。', '画Controller→Service代理→目标方法→Mapper。¦指出this调用从目标对象直接到自身，不经默认代理。¦说明回滚规则、配置与版本条件，再用数据库状态证明。', 'class DemoService {\n  public void outer() { this.inner(); }\n  @Transactional public void inner() { /* 多条SQL */ }\n}\n// 默认代理模式：outer内部this.inner不触发该次事务增强', 'java', '事务、IoC与MVC题必须能画时序；原理与工程失败测试结合比背类名有效。', 'AspectJ模式与代理模式不同；Spring6+类代理方法可见性细节不能用“只有public”概括全部。', '对比其他Bean调用inner与outer内部调用，注入异常并检查第一SQL是否回滚。', TX);
put('interview-3', '数据题应从SQL、版本、缓存传播与消息确认点推演状态。MyBatis参数化、MySQL隔离、Redis缓存与MQ投递是不同保证层。', '列初始数据和两个执行者步骤。¦在每读、写、提交、ack处标记已完成状态。¦枚举崩溃与重试，再用约束、幂等或修复解释正确方案。', '初始：processed_event无E，业务无效果\n消费：写业务+E → COMMIT → 崩溃（未ack）\n重投E：唯一event_id已存在 → 返回既有结果 → ack\n结论：重复投递，但业务效果一次', 'plaintext', '面试可选一个完整故障时序解释，不必同时背所有中间件宣传能力。', 'Broker确认不等于消费成功；数据库事务提交不等于HTTP结果收到；缓存命中不等于最新值。', '真实数据库与Broker注入崩溃点验证，确保去重与业务操作共享可靠边界。', 'https://www.rabbitmq.com/docs/confirms');
put('interview-4', '分布式场景题要求先明确约束再取舍；设计模式解释协作结构，治理机制限制资源与失败，不是把所有组件名列一遍。', '问核心结果需多快、哪支线能延迟、规模与故障模型。¦把最小方案放进主链：本地事务、可靠事件、消费者。¦解释超时、重试、幂等和恢复，以及为何暂不拆更多服务。', '问题：短信超时让创建员工很慢\n答案结构：确认通知可延迟 → 主事务只写员工+Outbox\n异步消费者发送；失败退避、幂等、积压告警\n边界：创建成功≠短信已送达', 'plaintext', '用具体约束证明方案；仅单实例低流量时也可说明简单后台任务的可靠性限制。', '面试没有唯一万能架构；条件变化，例如必须同步验证短信，将改变方案和失败策略。', '对每方案列成本和失败分支，改变一个约束后重新推理，而非沿用背诵答案。');
put('interview-5', '项目表达应基于本人完成且可核实的工作：问题、约束、实现、证据和限制。简历是可追问的事实摘要，八股知识应挂回调用链。', '先描述业务痛点与负责范围。¦选关键改动说明机制和被替代的失败路径。¦给测试或生产数据并标出处，说明未覆盖边界。', '可写：为重复创建加入唯一键与409映射，\n用两连接并发测试验证只生成一行。\n不可据此写：生产支持百万QPS、彻底零故障。\n可展示：SQL迁移、测试、调用链和失败日志。', 'plaintext', '准备项目陈述时优先能展示证据的改动；学习项目可明确作为模拟练习。', '本网站实验是教学模型，不是个人线上成果；不知道的负责范围不应编造。', '让同学追问每个指标来源和异常边界，若无法复现或说明就收窄表述。');
put('interview-6', '算法题练抽象与边界，场景题练取舍，排错题练证据。三者都需要讲出条件、步骤和验证，而不是先给一个猜测答案。', '算法先明确输入规模和结果语义，再写复杂度与边界。¦排错从范围、时间和变更线索开始，逐层采证。¦用最小实验验证候选原因，确认修复后无新风险。', '慢请求排查：\n入口耗时 → 连接池等待 → SQL/锁 → 外部API → GC/CPU\n若DB锁等待高：找阻塞事务并核对业务栈\n不要同时随机增线程、增池、加堆，使证据失去可比性', 'plaintext', '笔试代码要处理空、重复、溢出等；工程场景先定位，工具按假设选择。', 'CPU低不证明应用没有问题，ping通不证明API可用；一次日志也不能代表全部请求。', '提供带一个已知故障的场景，用实际指标检验诊断步骤能否缩小范围。');
put('interview-7', 'SQL手写、接口与系统设计把业务需求转为可执行契约；手写代码还要处理数据边界、权限、并发和错误。答案应连接需求到持久化与响应。', '定义资源、Method、参数位置和状态码。¦写Service规则和数据库约束，再给SQL与事务。¦验证成功、无记录、越权、冲突与超时后重试。', 'GET /employees/108 → 200或404/403\nSELECT id,username,name FROM employee\nWHERE tenant_id=? AND id=?;\nVO：只展示允许字段\n身份：tenantId来自可信认证，不是任意Query', 'plaintext', '按用例自然生出注解和SQL；具体语法可查，职责和边界不能丢。', '统一返回不代表所有情况200。PUT/PATCH/POST选择要按接口语义，不能只记“修改就PUT”。', '用独立客户端构造请求，测试租户、缺记录和不合法参数，并与Schema契约对照。');
put('interview-8', '项目亮点是具体难题得到可验证解决，难点表达展示推理和取舍。技术名称本身不证明贡献，失败边界能区分真实理解和背诵。', '描述可复现的问题，如并发查重竞态。¦说明错误方案为何失效，以及最终数据库约束和错误映射。¦给并发测试、迁移与限制，再回答重试、租户、大小写等追问。', '难题：两个请求都SELECT无同名后INSERT\n错误：仅在Service先查重\n修复：UNIQUE(tenant_id,username)+冲突映射\n证据：两个真实连接并发，只有一行\n追问：排序规则、幂等key、响应丢失', 'plaintext', '选能解释完整链和证据的一两个难点，不必宣称所有技术都精通。', '用单线程演示不能证明并发；简历数字必须说明环境、样本、口径和范围。', '拿代码、SQL、测试和trace回答连续追问，无法验证的收益应标假设或删除。');

// Final network/security conclusions, checked against RFC1918, IANA,
// Java Socket APIs and the browser HTTP header specifications.
conceptDetails['foundation-5'].boundaries = 'HTTP/3使用QUIC/UDP，因此TCP链不是所有HTTP唯一实现。RFC1918私有IPv4为10.0.0.0/8（10.0.0.0–10.255.255.255）、172.16.0.0/12（172.16.0.0–172.31.255.255）、192.168.0.0/16（192.168.0.0–192.168.255.255）；不是全部172.*或全部192.*，也不能把非私网地址都简单当公网可达。';
conceptDetails['foundation-6'].definition = 'DNS把名称解析成地址等记录；TCP提供可靠有序字节流，UDP提供数据报；Socket是通信端点和编程抽象，不是协议。IP+端口帮助定位端点，同一端口号的TCP/UDP属于不同传输命名空间。';
conceptDetails['foundation-6'].boundaries = '端口号字段范围0–65535。端口0保留；许多本地bind API传0表示让系统选择可用临时端口，并非普通服务对外监听0。权限、占用和策略另约束可绑定端口。TCP不加密、不提供消息边界、不承诺永久故障下交付，也不保证业务恰好一次；保密需TLS等安全层。';
conceptDetails['foundation-6'].mechanism.push('UDP完整区分数据报，TCP接收方须用长度、分隔符或应用协议恢复消息。服务器地址与端口要区分本地绑定和远端连接目标。');
conceptDetails['foundation-10'].boundaries += ' ping通常测试ICMP响应；能ping不证明TCP端口开放或HTTP业务正确，不能ping也可能仅被禁ICMP而HTTPS仍可访问。';
conceptDetails['web-12'].boundaries += ' CORS控制浏览器跨源访问响应权限；Referrer-Policy决定Referer来源信息随请求发送多少，二者不是同一安全机制。';
conceptDetails['enterprise-4'].decision = '生产登录使用成熟安全体系和经压测的编码成本；不要采用固定123456密码或MD5作为生产密码存储。';
conceptDetails['javase-15'].exampleCode = '# JDK21可执行JAR启动示例\njava -Xms512m -Xmx512m -Xlog:gc*:file=gc.log -jar app.jar';
conceptDetails['foundation-5'].source = 'https://www.rfc-editor.org/rfc/rfc1918.html';
conceptDetails['foundation-6'].source = 'https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/net/Socket.html';
conceptDetails['testing-3'].exampleCode = 'Notifier notifier = mock(Notifier.class);\ndoThrow(new IllegalStateException("simulated provider timeout"))\n  .when(notifier).send(anyString());\n// 注入替身调用Service，断言失败通知保留可重试状态';
conceptDetails['jvm-3'].exampleCode = 'java -Xms512m -Xmx512m -Xlog:gc*:file=gc.log:time,uptime,level,tags -jar app.jar';
conceptDetails['jvm-4'].exampleCode = 'java -Xmx512m -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/var/diag/app.hprof -jar app.jar\n# 诊断路径按实际系统设置，必须有权限与容量；转储含敏感对象';
// Use SQL-standard single-quoted string literals rather than relying on
// MySQL's non-ANSI double-quote mode in illustrative statements.
for (const detail of Object.values(conceptDetails)) {
  if (detail.language === 'sql') detail.exampleCode = detail.exampleCode.replace(/"([^"\n]*)"/g, (_, value) => `'${value}'`);
}
